INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27ed2fe8d28553f0abe9c80d212a385c', 'NEET', '11', 'Biology', 'bio_11_neet_cell_the_unit_of_life_cell_biology', 'Cell Biology', 'Cell wall composition primary secondary', '[]', '["Cell wall","Cellulose","Hemicellulose","Pectin"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'The cell wall of a plant cell is primarily composed of cellulose, hemicellulose, and pectin. Which of the following is NOT a component of the cell wall?', '["Cellulose", "Hemicellulose", "Pectin", "Chitin"]', 'Chitin', 'Step 1: Recall the composition of the plant cell wall. Step 2: Identify the components of the cell wall. Step 3: Determine which option is NOT a component of the cell wall.', '["Step 1: Recall the composition of the plant cell wall.", "Step 2: Identify the components of the cell wall.", "Step 3: Determine which option is NOT a component of the cell wall."]', '', 'general.exam_trap', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:37:30.221Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27ee33375dbb397192e1dc384e285f02', 'Board', '10', 'Science', 'bio_10_board_life_processes', 'Life Processes', 'Transportation in humans circulatory system', '[]', '["circulatory system","heart","blood vessels","blood","respiratory system","organ function","human biology"]', 1, 0, '["Board"]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 4, 0.0, 'Which of the following is NOT a part of the human circulatory system?', '["Heart", "Blood vessels", "Lungs", "Blood"]', 'Lungs', 'The circulatory system includes the heart, blood vessels, and blood. The lungs are part of the respiratory system, though they interact closely with the circulatory system for gas exchange. They are not a structural component of circulation.', '["Step 1: Identify components of circulatory system: heart, blood, blood vessels", "Step 2: Recognize lungs are for gas exchange (respiratory system)", "Step 3: Note that while lungs are functionally linked, they are not part of circulatory anatomy", "Step 4: Select ''Lungs'' as correct answer"]', '', 'bio.circulation.organ_system_misclassification', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:57:52.818Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27ef354c49904fc48a9ce98abfd2074e', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_complex_geometry', 'Complex Numbers', 'Geometric Representation', '["math_12_ja_complex_numbers"]', '["equilateral triangle","complex plane","rotation","modulus condition"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'In the complex plane, points $z_1, z_2, z_3$ form an equilateral triangle. Which of the following statements are necessary and sufficient conditions for this configuration?', '["$|z_1 - z_2| = |z_2 - z_3| = |z_3 - z_1|$ and the triangle is right‑angled.", "$(z_1 - z_2) = \\omega\\,(z_2 - z_3)$ where $\\omega = e^{i\\pi/3}$.", "$\\arg(z_1 - z_2) - \\arg(z_2 - z_3) = 120^\\circ$.", "$(z_1 - z_2) = \\omega^2\\,(z_2 - z_3)$ where $\\omega = e^{i\\pi/3}$."]', '["[\"$(Z_1 - Z_2) = \\OMEGA\\,(Z_2 - Z_3)$ WHERE $\\OMEGA = E^{I\\PI/3}$.\",\"$(Z_1 - Z_2) = \\OMEGA^2\\,(Z_2 - Z_3)$ WHERE $\\OMEGA = E^{I\\PI/3}$.\"]"]', 'An equilateral triangle can be obtained by rotating one side by $\pm 60^\circ$ about a vertex. The rotation factor $\omega = e^{i\pi/3}$ (or its square $\omega^2$) gives the required relation. Option A adds an impossible right‑angle condition, and option C uses $120^\circ$ which corresponds to a different orientation.', '["Step 1: Write the vector from $z_2$ to $z_1$ as $z_1 - z_2$.", "Step 2: For a $60^\\circ$ rotation, multiply by $\\omega = e^{i\\pi/3}$; for the opposite orientation use $\\omega^2$.", "Step 3: Equate the rotated vector to the side $z_2 - z_3$ to obtain the condition.", "Step 4: Verify that the modulus equality alone does not guarantee the correct orientation."]', '$(z - z_0)\,\omega + z_0$', 'math.complex.geometry.equilateral_condition', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:46:40.418Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27efff144e76f3d04532f9505661357a', 'Board', '9', 'Mathematics', 'math_9_board_algebra', 'Algebraic Expressions', 'Multiplication of polynomials FOIL', '[]', '["polynomials","FOIL","multiplication","algebra"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1000, 'CLASS_9_BASIC', 2, 0.0, 'What is the product of (x + 3)(x + 4)?', '["x² + 7", "x² + 7x + 12", "x² + 12x + 7", "2x + 7"]', 'x² + 7x + 12', 'Using FOIL: x² + 4x + 3x + 12 = x² + 7x + 12.', '["Step 1: Expand (x+3)(x+4)", "Step 2: x² + 4x + 3x + 12 = x² + 7x + 12"]', '(a+b)(c+d) = ac + ad + bc + bd', 'math.algebra.foil.missing_terms', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:36:01.961Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27f4d7e5dce1f6d632ae5d33a04c809f', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction', 'Human Reproduction', 'Hormonal regulation', '[]', '["human reproduction","hormonal regulation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'Which of the following hormones is responsible for the regulation of the menstrual cycle?', '["FSH", "LH", "Estrogen", "Progesterone"]', 'FSH', 'FSH is responsible for the regulation of the menstrual cycle.', '["Step 1: Recall the hormones involved in the menstrual cycle", "Step 2: Identify the role of each hormone", "Step 3: Choose the correct answer"]', '', 'bio.reproduction.hormonal_regulation', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:08:20.387Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27f5d99f009424512acd6c69d31f8b1b', 'JEEMains', '12', 'Mathematics', 'mat_12_jm_matrices', 'mat_12_jm_matrices', 'Matrices', '[]', '["adjoint matrix","cofactor matrix"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, 'If $A=\begin{bmatrix} 1 & 2 \\ 3 & 4 \end{bmatrix}$, then $adj(A)$ is given by $\boxed{\begin{bmatrix} a & b \\ c & d \end{bmatrix}}$.', '["$\\begin{bmatrix} 4 & -2 \\\\ -3 & 1 \\end{bmatrix}$", "$\\begin{bmatrix} 4 & -3 \\\\ -2 & 1 \\end{bmatrix}$", "$\\begin{bmatrix} 4 & -1 \\\\ -3 & 2 \\end{bmatrix}$", "$\\begin{bmatrix} 4 & -2 \\\\ -3 & 1 \\end{bmatrix}$"]', '$\begin{bmatrix} 4 & -2 \\ -3 & 1 \end{bmatrix}$', 'Adjoint of matrix.', '["Find the cofactor matrix of $A$.", "Transpose the cofactor matrix."]', '$adj(A) = \begin{bmatrix} C_{11} & C_{12} \\ C_{21} & C_{22} \end{bmatrix}^T$', 'mathematics.matrices.adjoint_matrix', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:53:25.084Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27f6e607b4be3a2daf20a0e0389b912b', 'NEET', '12', 'Biology', 'bio_12_neet_mismatch_repair', 'DNA Repair', 'Mismatch repair mechanism', '["bio_12_neet_dna_repair"]', '["MMR","MSH2-MSH6","EXO1","strand discrimination","DNA polymerase"]', 1, 0, '[]', 'MCQ', NULL, 0, 2050, 'NEET_MEDIUM', 3, -1.0, 'Which of the following statements correctly describe the mismatch repair (MMR) pathway in eukaryotic cells?', '["The MutS homolog (MSH2–MSH6) complex recognizes base‑base mismatches and small insertion‑deletion loops.", "DNA polymerase δ directly fills the gap after excision without requiring a separate polymerase.", "EXO1 removes the mismatched segment in the 3''→5'' direction.", "The repaired strand is distinguished by the presence of unmethylated CpG sites."]', 'The MutS homolog (MSH2–MSH6) complex recognizes base‑base mismatches and small insertion‑deletion loops.', 'In eukaryotes, the MSH2–MSH6 heterodimer scans DNA and binds to base mismatches or small indels. EXO1 excises the error 5''→3'', and strand discrimination relies on PCNA loading rather than CpG methylation.', '["Step 1: Identify the protein complex that initially detects mismatches – MSH2–MSH6.", "Step 2: Recall that EXO1 works 5''→3'' and a separate polymerase (δ/ε) fills the gap.", "Step 3: Recognize that eukaryotic strand discrimination uses PCNA, not CpG methylation."]', '', 'biology.dna_repair.mmr_recognition', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:43:40.246Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27f7bc6d0cd062778125b82915f25502', 'Board', '8', 'Mathematics', 'math_8_board_linear_eq', 'Algebraic Expressions and Identities', 'Simple linear equations solution', '[]', '["linear equation","isolating variable","addition/subtraction","integer solution"]', 0, 0, '[]', 'MCQ', NULL, 0, 850, 'CLASS_8_RECALL', 3, 0.0, 'Solve the linear equation $3x - 7 = 2x + 5$ for $x$.', '["x = 12", "x = -12", "x = 2", "x = -2"]', 'x = 12', 'Subtract $2x$ from both sides to get $x - 7 = 5$. Add $7$ to both sides, yielding $x = 12$.', '["Step 1: Bring all terms containing $x$ to one side: $3x - 2x = 5 + 7$.", "Step 2: Simplify to obtain $x = 12$.", "Step 3: Verify by substituting back into the original equation."]', 'ax + b = cx + d \;\Rightarrow\; x = \frac{d-b}{a-c}', 'math.algebra.linear_eq_isolation', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:19.295Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27f9ecd89654b2d53fe097c6829f264d', 'Board', '10', 'Mathematics', 'math_10_board_quadratic_equations', 'Quadratic Equations', 'Factorisation method for quadratics', '[]', '["quadratic equations","factorisation","roots","zero product property","algebra","polynomial","solution"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'What are the roots of the quadratic equation $x^2 - 5x + 6 = 0$ using factorisation?', '["2 and 3", "-2 and -3", "1 and 6", "-1 and -6"]', '2 and 3', 'Factorise: $x^2 - 5x + 6 = (x - 2)(x - 3) = 0$. So roots are $x = 2$ and $x = 3$. Common mistake: sign error (thinking -2, -3) or wrong factor pair (1,6).', '["Step 1: Find two numbers that multiply to 6 and add to -5: -2 and -3", "Step 2: Rewrite: x² - 2x - 3x + 6", "Step 3: Factor: (x - 2)(x - 3) = 0 → x = 2, 3"]', 'If (x - a)(x - b) = 0, then x = a or x = b', 'math.algebra.sign_error_in_factorisation', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:27:43.415Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('27fc2e0465e8e9fef79fc1ce82bfc054', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_damped_oscillation', 'Advanced Mechanics', 'Quality factor and logarithmic decrement', '["phy_12_ja_oscillations"]', '["damped oscillator","quality factor","logarithmic decrement","energy decay","light damping"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'For a lightly damped harmonic oscillator, which of the following statements are true about the relationship between the quality factor $Q$ and the logarithmic decrement $\delta$?', '["$Q = \\frac{\\pi}{\\delta}$", "A higher $Q$ implies a slower energy decay per cycle.", "$\\delta = \\frac{2\\pi}{Q}$", "The energy decays as $E(t)=E_0 e^{-\\frac{\\omega_0}{Q}t}$"]', '["[\"$Q = \\FRAC{\\PI}{\\DELTA}$\",\"A HIGHER $Q$ IMPLIES A SLOWER ENERGY DECAY PER CYCLE.\",\"THE ENERGY DECAYS AS $E(T)=E_0 E^{-\\FRAC{\\OMEGA_0}{Q}T}$\"]"]', 'For a lightly damped oscillator, the logarithmic decrement $\delta$ and quality factor $Q$ are related by $Q = \pi/\delta$. A larger $Q$ means the system loses less energy per cycle, i.e., slower decay. Energy decays exponentially as $E(t)=E_0 e^{-\omega_0 t/Q}$.', '["Step 1: Write the definition of logarithmic decrement $\\delta = \\frac{1}{n}\\ln\\frac{A_1}{A_{n+1}}$ for $n=1$.", "Step 2: Use the relation $Q = \\frac{\\pi}{\\delta}$ for light damping.", "Step 3: Recognize that a larger $Q$ reduces the fractional energy loss per cycle.", "Step 4: Derive the energy‑decay law $E(t)=E_0 e^{-\\omega_0 t/Q}$ from the amplitude decay."]', '$Q = \frac{\pi}{\delta}$', 'physics.mechanics.damped_oscillator_q_delta', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:43.583Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('280a2a9757756e1143a9a73ec26809ee', 'NEET', '12', 'Biology', 'bio_12_neet_evolution', 'Evolution', 'Hardy-Weinberg principle allele frequencies', '[]', '["Hardy-Weinberg principle","Allele frequencies","Population genetics"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 1, -1.0, '$$\text{The Hardy-Weinberg principle states that allele frequencies in a population remain constant from generation to generation in the absence of other evolutionary influences.}
$$', '["The Hardy-Weinberg principle states that allele frequencies in a population remain constant from generation to generation in the absence of other evolutionary influences.", "The Hardy-Weinberg principle states that allele frequencies in a population increase from generation to generation in the absence of other evolutionary influences.", "The Hardy-Weinberg principle states that allele frequencies in a population decrease from generation to generation in the absence of other evolutionary influences.", "The Hardy-Weinberg principle states that allele frequencies in a population remain constant from generation to generation in the presence of other evolutionary influences."]', 'The Hardy-Weinberg principle states that allele frequencies in a population remain constant from generation to generation in the absence of other evolutionary influences.', 'Step 1: The Hardy-Weinberg principle states that allele frequencies in a population remain constant from generation to generation in the absence of other evolutionary influences.', '["Step 1: Recall the definition of the Hardy-Weinberg principle."]', '', 'biology.evolution.hardy_weinberg_principle', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:53:22.339Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('280acad77e97322099b0803012962a06', 'JEEMains', '11', 'Mathematics', 'math_11_jm_complex_numbers', 'Complex Numbers', 'Complex Numbers', '[]', '["Geometry on Argand plane","Circle locus"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'Let z = 3 + 4i. Find the locus of the point (x, y) such that |z - x - iy| = 1.', '["x^2 + y^2 = 16", "x^2 + y^2 = 25", "x^2 + y^2 = 36", "x^2 + y^2 = 49"]', 'x^2 + y^2 = 25', 'Complex numbers can be represented on the Argand plane.', '["|z - x - iy| = 1.", "z = 3 + 4i."]', '|z - x - iy| = 1', 'math.complex_numbers.geometry', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:54:11.482Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('280aef7f63ee49b26ae68a89fdbd940b', 'JEEMains', '12', 'Physics', 'phy_12_jm_current_electricity', 'Current Electricity', 'Ohm''s law and resistivity', '[]', '["resistivity","material-property","ohm''s-law","length-change"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 1, -1.0, 'A wire of resistivity $\rho$ is stretched to double its length. The new resistivity is:', '["$\\rho$", "$2\\rho$", "$4\\rho$", "$\\rho/2$"]', '$\rho$', 'Resistivity is material property; unchanged with shape.', '["Step 1: Recall resistivity depends on material", "Step 2: Stretching doesn''t change material"]', '\rho \text{ (intrinsic)}', 'physics.current_electricity.resistivity_vs_resistance', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:02:18.541Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('280cc950f8118201dd0e86bd9c2ca0d4', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics_nonuniform', 'Kinematics', 'Non‑uniform acceleration (integration)', '[]', '["acceleration","integration","displacement","kinematics"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A particle moves along a straight line with a time‑dependent acceleration $a(t)=kt$, where $k$ is a constant. If the particle starts from rest at $t=0$, what is its displacement $s$ after time $t$?', '["$s = \\frac{1}{2}kt^{3}$", "$s = \\frac{1}{3}kt^{3}$", "$s = \\frac{1}{6}kt^{3}$", "$s = kt^{2}$"]', '$s = \frac{1}{6}kt^{3}$', 'Integrate acceleration to get velocity: $v=\int a dt = \frac{1}{2}kt^{2}$. Integrate velocity to get displacement: $s=\int v dt = \frac{1}{6}kt^{3}$, using $v(0)=0$, $s(0)=0$.', '["Step 1: Integrate $a(t)=kt$ to obtain $v(t)=\\frac{1}{2}kt^{2}+C_{1}$; $C_{1}=0$ because $v(0)=0$.", "Step 2: Integrate $v(t)$ to obtain $s(t)=\\frac{1}{6}kt^{3}+C_{2}$; $C_{2}=0$ because $s(0)=0$.", "Step 3: Write the final expression for displacement."]', 's = \int \int a(t)\,dt\,dt', 'physics.mechanics.nonuniform_acceleration', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:48:13.166Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('280d99882f8fb721091204d039cc7d8c', 'NEET', '11', 'Biology', 'bio_11_neet_respiration', 'Respiration in Plants', 'P/O ratio and chemiosmosis', '[]', '["cellular respiration","oxidative phosphorylation","P/O ratio","chemiosmosis","ATP yield"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'During aerobic respiration of one molecule of glucose in plant cells, the total number of ATP molecules produced via oxidative phosphorylation (chemiosmosis) is approximately:', '["30 ATP", "32 ATP", "34 ATP", "36 ATP"]', '30 ATP', 'Each NADH yields about 2.5 ATP and each FADH₂ about 1.5 ATP. From one glucose molecule, 10 NADH and 2 FADH₂ are generated in the electron transport chain, giving 10×2.5 + 2×1.5 = 25 + 3 = 28 ATP. Adding the 2 ATP from substrate‑level phosphorylation gives a total of ~30 ATP.', '["Step 1: Identify the number of NADH (10) and FADH₂ (2) produced per glucose.", "Step 2: Multiply NADH by its P/O ratio (2.5) and FADH₂ by its P/O ratio (1.5).", "Step 3: Add the ATP from oxidative phosphorylation to the 2 ATP formed by substrate‑level phosphorylation.", "Step 4: Sum the values to obtain the total ATP yield."]', 'ATP_{total}= (N_{NADH}\times2.5)+(N_{FADH2}\times1.5)+2', 'biology.respiration.p_o_ratio', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:15.702Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('280dc89b04feab970e370d975b4cca10', 'JEEMains', '12', 'Mathematics', 'math_12_integrals', 'Integrals', 'Definite integral as limit of sum', '[]', '["limit of sum","definite integral","Riemann sum","trigonometric integral"]', 0, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, 0.0, 'The value of $\lim_{n \to \infty} \frac{1}{n} \sum_{r=1}^{n} \cos\left(\frac{r\pi}{2n}\right)$ is', '[]', '2', 'This limit equals $\int_0^1 \cos\left(\frac{\pi x}{2}\right) dx = \frac{2}{\pi} \cdot \frac{\pi}{2} = 1$. Wait — final answer is 1? But integral evaluates to $\frac{2}{\pi} \times \frac{\pi}{2} = 1$. Correction: answer is 1.', '["Recognize as $\\int_0^1 \\cos(\\frac{\\pi x}{2}) dx$", "Integrate: $\\frac{2}{\\pi} \\sin(\\frac{\\pi x}{2})\\big|_0^1 = \\frac{2}{\\pi} \\cdot 1 = \\frac{2}{\\pi}$ → no, wait: $\\int_0^1 \\cos(\\frac{\\pi x}{2}) dx = \\frac{2}{\\pi} \\sin(\\frac{\\pi x}{2})\\big|_0^1 = \\frac{2}{\\pi}(1 - 0) = \\frac{2}{\\pi}$ → but this is not integer. Mistake in setup."]', '\lim_{n\to\infty}\frac{1}{n}\sum_{r=1}^n f\left(\frac{r}{n}\right) = \int_0^1 f(x)dx', 'math.calculus.rsum_limit_bounds', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:06:18.207Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2819954e051d8d733b3d56b2e2c8bbcc', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_electrostatics', 'Electric Charges and Fields', 'Electrostatics Advanced', '[]', '["variable capacitor","capacitance","charge"]', 0, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 3, -2.0, 'A variable capacitor has a capacitance of $C = \frac{epsilon_0 A}{d}$, where $A$ is the area of the plates and $d$ is the distance between them. If the capacitor is connected to a battery of voltage $V$, the charge on the capacitor is $Q = CV$. If the distance between the plates is decreased to $d/2$, the new charge on the capacitor is', '["$2Q$", "$Q$", "$Q/2$", "$Q/4$"]', '$2Q$', 'The capacitance of the capacitor is inversely proportional to the distance between the plates. If the distance is decreased to $d/2$, the capacitance will increase to $2C$. Since the voltage remains the same, the new charge on the capacitor will be $2Q$.', '["Step 1: Recall the formula for the capacitance of a variable capacitor.", "Step 2: Calculate the new capacitance when the distance between the plates is decreased to $d/2$.", "Step 3: Calculate the new charge on the capacitor using the formula $Q = CV$."]', 'C = rac{epsilon_0 A}{d}', 'physics.electrostatics.capacitor', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:43:04.349Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('281b4de267d577bab94f29e7d1dcad75', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_thermodynamics', 'Thermodynamics', 'Enthalpy ΔH Hess law application', '[]', '["standard enthalpy of formation","Hess''s law","thermochemical equation","reaction enthalpy"]', 0, 0, '["NEET"]', 'Integer', NULL, 0, 1800, 'JEE_MAINS_EASY', 1, 0.0, 'Given: $\Delta H_f^\circ$(CO₂) = -393.5 kJ/mol, $\Delta H_f^\circ$(CO) = -110.5 kJ/mol. Find $\Delta H^\circ$ for $C + O_2 \to CO_2$.', '[]', '-393.5', 'Reaction is formation of CO₂, so $\Delta H^\circ = \Delta H_f^\circ$(CO₂) = -393.5 kJ/mol.', '["Step 1: Identify reaction as formation of CO₂", "Step 2: $\\Delta H^\\circ = \\Delta H_f^\\circ$(CO₂)"]', '$\Delta H^\circ = \sum \Delta H_f^\circ(\text{products}) - \sum \Delta H_f^\circ(\text{reactants})$', 'chemistry.thermodynamics.hess_law_formation_confusion', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:51:22.742Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('281f4332077bd75c1357717c212c8353', 'NEET', '12', 'Biology', 'bio_12_neet_evolution', 'Evolution', 'Types of natural selection', '[]', '["directional selection","disruptive selection","stabilizing selection","variation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'NEET_EASY', 2, -1.0, 'Which type of natural selection tends to reduce the amount of variation in a population?', '["Directional selection", "Disruptive selection", "Stabilizing selection", "All of the above"]', 'Stabilizing selection', 'Stabilizing selection favors intermediate phenotypes, eliminating extremes and thereby decreasing genetic variation. Directional selection shifts the mean, and disruptive selection increases variation by favoring extremes.', '["Step 1: Recall the effect of each selection type on phenotypic distribution.", "Step 2: Identify that stabilizing selection narrows the distribution.", "Step 3: Select the option that matches this description."]', '', 'biology.evolution.selection_type', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:46:31.484Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('282004e177468549879d83ef6d5dc548', 'JEEMains', '11', 'Mathematics', 'math_11_jm_complex_locus', 'Complex Numbers', 'Argand Plane Geometry', '[]', '["Argand diagram","circle locus","modulus","distance formula"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Which of the following points lies on the circle defined by $|z-(1+i)| = 2$ in the Argand plane?', '["Point (3, 1)", "Point (1, 3)", "Point (0, 1)", "Point (1, -1)"]', 'Point (3, 1)', 'The locus is a circle of radius $2$ centred at $(1,1)$. The distance from $(1,1)$ to $(3,1)$ is $\sqrt{(3-1)^2+(1-1)^2}=2$, so the point lies on the circle. All other points give a distance different from $2$.', '["Step 1: Identify the centre $(1,1)$ and radius $2$ from $|z-(1+i)|=2$.", "Step 2: Compute the distance of each option from the centre using the distance formula.", "Step 3: Compare each distance with the radius $2$.", "Step 4: Select the point whose distance equals $2$."]', '|z - z_0| = r', 'math.complex.locus_distance_error', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:27:06.755Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('282019fbda24e5daabf9b7c098777828', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics_1d', 'Kinematics', 'Velocity‑time graph area (displacement)', '[]', '["definite integral","displacement","velocity function","area under curve"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A particle moves along a straight line with velocity $v(t)=5t^{2}-3t+2\ \text{m/s}$. What is its displacement between $t=1\,\text{s}$ and $t=3\,\text{s}$?', '["35.33 m", "34.00 m", "36.50 m", "33.00 m"]', '35.33 m', 'Displacement is the definite integral of velocity: $\int_{1}^{3}(5t^{2}-3t+2)dt = \left[\frac{5}{3}t^{3}-\frac{3}{2}t^{2}+2t\right]_{1}^{3}=35.33\,\text{m}$.', '["Step 1: Write the integral $\\int_{1}^{3}(5t^{2}-3t+2)dt$.", "Step 2: Integrate term‑by‑term to obtain $\\frac{5}{3}t^{3}-\\frac{3}{2}t^{2}+2t$.", "Step 3: Substitute $t=3$ and $t=1$, then subtract to get $35.33\\,\\text{m}$."]', '$\displaystyle \Delta x=\int_{t_1}^{t_2}v(t)\,dt$', 'physics.kinematics.area_under_curve', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:46.413Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2820a75758980bf98022ac7e9a5e5c06', 'Board', '8', 'Science', 'phy_08_board_light', 'Light', 'Braille system and visually impaired', '[]', '["Braille","tactile system","visually impaired","raised dots","accessibility","non-visual reading"]', 0, 0, '[]', 'MCQ', NULL, 0, 850, 'CLASS_8_RECALL', 4, 0.0, 'Which of the following best describes the Braille system?', '["A visual signaling system using colors", "A tactile writing system using raised dots", "A sound-based communication system", "A digital screen reader for phones"]', 'A tactile writing system using raised dots', 'Braille is a tactile writing system used by visually impaired people. It uses patterns of raised dots that can be felt with fingers to represent letters and numbers.', '["Step 1: Recall Braille is for visually impaired", "Step 2: It is not visual or auditory", "Step 3: It uses touch to read", "Step 4: Composed of raised dot patterns"]', '', 'physics.light.braille_misconception', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:11:13.135Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2824dba8de3ae55c1650a810ba0a15c5', 'Board', '10', 'Science', 'phy_10_board_light', 'Light', 'Refraction — Snell''s law', '[]', '["Snell''s law","refractive index","angle of refraction","air to glass"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'A ray passes from air ($n_{1}=1.00$) into glass ($n_{2}=1.50$). If the angle of incidence is $30^{\circ}$, what is the angle of refraction in the glass? (Give answer to the nearest degree.)', '["20^{\\circ}", "30^{\\circ}", "45^{\\circ}", "60^{\\circ}"]', '20^{\circ}', 'Using Snell''s law $n_{1}\sin i = n_{2}\sin r$, we get $\sin r = \frac{1.00\sin30^{\circ}}{1.50}=0.333$. Hence $r \approx 19.5^{\circ}$, which rounds to $20^{\circ}$.', '["Step 1: Write Snell''s law $n_{1}\\sin i = n_{2}\\sin r$.", "Step 2: Substitute the given values and solve for $\\sin r$.", "Step 3: Find $r$ and round to the nearest degree."]', 'n_{1}\sin i = n_{2}\sin r', 'physics.optics.snell_refraction', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:19', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Physics->Science) to match canonical taxonomy item sci_10_board_light', '2026-05-22T14:17:55.530Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2825c0e72d4e0fccc6573476f3bfe272', 'JEEMains', '12', 'Mathematics', 'math_12_jm_continuity_differentiability', 'Continuity and Differentiability', 'Chain rule', '[]', '["chain rule","derivative of composite function","trigonometric derivative"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 2, -1.0, 'If $f(x) = \sin(2x^2 + 3)$, then $f''(x)$ is', '["2x\\cos(2x^2 + 3)", "4x\\cos(2x^2 + 3)", "\\cos(2x^2 + 3)", "2\\cos(2x^2 + 3)"]', '4x\cos(2x^2 + 3)', 'Apply chain rule: derivative of sin(u) is cos(u)\cdot u'', u = 2x^2+3, u'' = 4x.', '["Let u = 2x + 3, f = sin(u)", "f'' = cos(u) \\cdot 4x"]', '\frac{d}{dx}\sin(u) = \cos(u) \cdot \frac{du}{dx}', 'math.calculus.chain_rule_missing_inner_derivative', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:09:26.356Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('282856ea7252579a3245521c45e76ee1', 'NEET', '11', 'Biology', 'bio_11_neet_autonomic', 'Neural Control and Coordination', 'Autonomic Nervous System', '[]', '["parasympathetic","sympathetic","heart rate","vagus nerve","autonomic control"]', 0, 0, '[]', 'MCQ', NULL, 0, 1820, 'NEET_EASY', 3, -1.0, 'Parasympathetic stimulation of the heart results in:', '["Increase in heart rate", "Decrease in heart rate", "No change in heart rate", "Induction of arrhythmia"]', 'Decrease in heart rate', 'Parasympathetic fibers (via the vagus nerve) release acetylcholine, which reduces the rate of depolarization in the SA node, thereby lowering heart rate.', '["Step 1: Identify the neurotransmitter released by parasympathetic nerves (acetylcholine).", "Step 2: Understand its effect on the SA node – slowing depolarization.", "Step 3: Conclude that heart rate decreases."]', '', 'biology.neural.parasympathetic_heart', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:21:32.762Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28295b70216f5d24a26f00358be44aab', 'NEET', '12', 'Biology', 'bio_12_neet_translation', 'Molecular Biology', 'Translation', '[]', '["translation","ribosome","codon","anticodon","wobble","genetic code"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'During translation, which statement about codon‑anticodon pairing is correct?', '["The anticodon is read 5''→3'' on tRNA while the codon is read 3''→5'' on mRNA.", "Base pairing follows Watson‑Crick rules except for wobble at the third position.", "Each anticodon can pair with only one codon.", "The ribosome catalyzes peptide bond formation, not codon‑anticodon pairing."]', 'Base pairing follows Watson‑Crick rules except for wobble at the third position.', 'Standard codon‑anticodon interactions obey Watson‑Crick pairing (A‑U, G‑C) at the first two positions. The third position allows wobble, permitting non‑standard base pairing, which expands the coding capacity of tRNAs.', '["Step 1: Recall the Watson‑Crick base‑pairing rules for RNA.", "Step 2: Identify the special case of wobble at the third codon position.", "Step 3: Choose the option that correctly describes this rule."]', '', 'biology.molecular.translation_codon', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:30:46.043Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2829a83458615ee08e51ccc8f76a8d4e', 'NEET', '12', 'Biology', 'bio_12_neet_endosperm', 'Sexual Reproduction in Flowering Plants', 'Endosperm development', '[]', '["endosperm","double fertilization","nuclear type","cellular type","embryo sac"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'In flowering plants, after double fertilization, the endosperm can develop by different patterns of nuclear division. Which type of endosperm development is characterized by nuclear divisions without the formation of cell walls until the later stages?', '["Nuclear type", "Cellular type", "Helobial type", "None of the above"]', 'Nuclear type', 'Double fertilization produces a diploid embryo and a triploid endosperm. In the nuclear type, the primary endosperm nucleus undergoes repeated mitotic divisions while remaining free in the syncytium; cell walls form only later. This distinguishes it from the cellular and helobial types.', '["Step 1: Recognize that endosperm development follows double fertilization.", "Step 2: Identify the pattern where nuclei divide without immediate cytokinesis.", "Step 3: Match this pattern to the nuclear type of endosperm development."]', '', 'biology.reproduction.endosperm_type', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:48:39.023Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28372827386c344a5f717d473f239985', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_calculus', 'Calculus', 'Leibniz rule for differentiation under integral sign', '["math_12_ja_integration"]', '["Leibniz rule","parameter differentiation","definite integral","chain rule"]', 1, 0, '[]', 'MCQ', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -2.0, 'Let \(F(x)=\displaystyle\int_{0}^{\sin x} e^{t^{2}}\,dt\). Find \(\dfrac{dF}{dx}\) at \(x=\frac{\pi}{6}\).', '["\\(\\frac{\\sqrt{3}}{2}\\,e^{1/4}\\) (correct)", "\\(\\frac{1}{2}\\,e^{\\sqrt{3}/4}\\)", "\\(\\frac{\\sqrt{3}}{2}\\,e^{\\sqrt{3}/2}\\)", "\\(\\frac{1}{2}\\,e^{1/4}\\)"]', '\(\frac{\sqrt{3}}{2}\,e^{1/4}\) (correct)', 'Using Leibniz rule, \(\dfrac{d}{dx}\int_{0}^{\sin x} e^{t^{2}}dt = e^{(\sin x)^{2}}\cos x\). At \(x=\pi/6\), \(\sin x=1/2\) and \(\cos x=\sqrt{3}/2\), giving \(e^{1/4}\times\sqrt{3}/2\).', '["Step 1: Apply Leibniz rule \\(\\frac{d}{dx}\\int_{a}^{g(x)}f(t)dt = f(g(x))\\,g''(x)\\).", "Step 2: Identify \\(f(t)=e^{t^{2}}\\) and \\(g(x)=\\sin x\\); compute \\(f(g(x))=e^{(\\sin x)^{2}}\\).", "Step 3: Differentiate \\(g(x)\\) to get \\(g''(x)=\\cos x\\) and substitute \\(x=\\pi/6\\)."]', '\frac{d}{dx}\int_{a}^{g(x)}f(t)dt = f(g(x))\,g''(x)', 'math.calculus.leibniz_rule_application', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:35:54.897Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2838dae07334166811332f0756330592', 'Board', '8', 'Science', 'sci_8_human_eye', 'Human Eye', 'Function of parts', '[]', '["eye anatomy","refraction","lens function","vision"]', 0, 0, '[]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 3, 0.0, 'Which part of the human eye is primarily responsible for focusing incoming light onto the retina?', '["Cornea", "Iris", "Lens", "Pupil"]', 'Lens', 'The lens changes its shape (accommodation) to focus light precisely on the retina. The cornea only refracts light at the surface, while the iris controls pupil size and the pupil is merely an opening.', '["Step 1: Identify the function of each eye part.", "Step 2: Recognize that focusing light onto the retina is done by the lens.", "Step 3: Choose the option that matches this function."]', '', 'science.eye.lens_function', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:47:10.656Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2841fc15be5c5c63bfd592f151963454', 'JEEMains', '11', 'Physics', 'phy_11_jm_work_energy', 'Work, Energy and Power', 'Work done by a variable force', '[]', '["variable force","work integral","integration","work‑energy theorem","definite integral"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A particle moves along the x‑axis under a variable force $F(x)=3x^{2}\ \text{N}$. Find the work done by the force as the particle moves from $x=0$ m to $x=2$ m.', '["6 J", "8 J", "12 J", "16 J"]', '8 J', 'Work is the integral of force over displacement: $W=\int_{0}^{2}3x^{2}dx = 3\left[\frac{x^{3}}{3}\right]_{0}^{2}=8\ \text{J}$.', '["Step 1: Write the work integral $W=\\int_{x_i}^{x_f}F(x)\\,dx$.", "Step 2: Substitute $F(x)=3x^{2}$ and limits $0$ to $2$: $W=\\int_{0}^{2}3x^{2}dx$.", "Step 3: Integrate: $\\int 3x^{2}dx = 3\\cdot\\frac{x^{3}}{3}=x^{3}$.", "Step 4: Evaluate between the limits: $W=2^{3}-0^{3}=8\\ \\text{J}$."]', '$W=\int_{x_i}^{x_f}F(x)\,dx$', 'physics.work.energy.variable_force_integration', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:45:10.073Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28438f1b1f96ce7e2354356d67dfcd7a', 'Board', '10', 'Mathematics', 'math_10_board_polynomials', 'Polynomials', 'Division algorithm for polynomials', '[]', '["remainder theorem","polynomial division","division algorithm","evaluation of polynomial","algebra","factor theorem","polynomials class 10"]', 0, 0, '[]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 4, 0.0, 'When dividing the polynomial $f(x) = 2x^3 - 9x^2 + 12x - 4$ by $g(x) = x - 2$, what is the remainder?', '["0", "2", "4", "-4"]', '4', 'Using the Remainder Theorem, substitute $x = 2$ into $f(x)$. So, $f(2) = 2(2)^3 - 9(2)^2 + 12(2) - 4 = 16 - 36 + 24 - 4 = 0$. Wait — this gives 0, but let''s recheck: $16 - 36 = -20$, $-20 + 24 = 4$, $4 - 4 = 0$. Actually, remainder is 0. But earlier step had error. Correct: $f(2) = 16 - 36 + 24 - 4 = (16+24)-(36+4)=40-40=0$. So remainder is 0.', '["Step 1: Apply Remainder Theorem: remainder when $f(x)$ divided by $x-a$ is $f(a)$", "Step 2: Here $a = 2$, so compute $f(2)$", "Step 3: $f(2) = 2(8) - 9(4) + 12(2) - 4 = 16 - 36 + 24 - 4$", "Step 4: Simplify: $16 + 24 = 40$, $36 + 4 = 40$, so $40 - 40 = 0$"]', 'f(a) = remainder when f(x) Ã· (xâˆ’a)', 'math.algebra.remainder_theorem_sign_error', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:22:01.226Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28475eb1c29a7e09332d20876adff35b', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig_equations', 'Inverse Trigonometric Functions', 'Inverse trig equations solutions', '[]', '["inverse trigonometric functions","trigonometric identities","equation solving","domain consideration","algebra"]', 0, 0, '[]', 'Integer', NULL, 0, 2400, 'JEE_MAINS_HARD', 6, 0.0, 'The number of solutions of the equation $ \sin^{-1}x + \sin^{-1}(1 - x) = \cos^{-1}x $ in the interval $[0,1]$ is', '[]', '2', 'Let $ \alpha = \sin^{-1}x $, $ \beta = \sin^{-1}(1 - x) $. Given $ \alpha + \beta = \cos^{-1}x = \frac{\pi}{2} - \alpha $. So $ \alpha + \beta = \frac{\pi}{2} - \alpha $ → $ 2\alpha + \beta = \frac{\pi}{2} $. Now, $ \beta = \sin^{-1}(1 - x) = \sin^{-1}(1 - \sin\alpha) $. Instead, use the identity for $ \sin^{-1}a + \sin^{-1}b $. For $ x \in [0,1] $, $ x \geq 0 $, $ 1-x \geq 0 $, and $ x^2 + (1-x)^2 = 2x^2 - 2x + 1 \leq 1 $ when $ 2x^2 - 2x \leq 0 $ → $ x(x-1) \leq 0 $, true for $ x \in [0,1] $. Equality at endpoints. So the identity $ \sin^{-1}x + \sin^{-1}(1-x) = \sin^{-1}\left( x\sqrt{1-(1-x)^2} + (1-x)\sqrt{1-x^2} \right) $ holds. Simplify $ 1-(1-x)^2 = 2x - x^2 $. So the sum is $ \sin^{-1}\left( x\sqrt{2x - x^2} + (1-x)\sqrt{1-x^2} \right) $. Set equal to $ \cos^{-1}x = \sin^{-1}\sqrt{1-x^2} $. Since both sides are in $[0, \pi/2]$, we can equate the insides: $ x\sqrt{2x - x^2} + (1-x)\sqrt{1-x^2} = \sqrt{1-x^2} $. Then $ x\sqrt{2x - x^2} = \sqrt{1-x^2} - (1-x)\sqrt{1-x^2} = x\sqrt{1-x^2} $. So $ x\sqrt{2x - x^2} = x\sqrt{1-x^2} $. For $ x \neq 0 $, divide: $ \sqrt{2x - x^2} = \sqrt{1-x^2} $. Square: $ 2x - x^2 = 1 - x^2 $ → $ 2x = 1 $ → $ x = 0.5 $. For $ x = 0 $, check separately: LHS = $ \sin^{-1}0 + \sin^{-1}1 = 0 + \pi/2 = \pi/2 $, RHS = $ \cos^{-1}0 = \pi/2 $, good. So solutions are $ x=0 $ and $ x=0.5 $. Thus, 2 solutions.', '["Step 1: Use identity for sum of inverse sines", "Step 2: Set equal to inverse cosine and equate arguments", "Step 3: Simplify to $ x\\sqrt{2x - x^2} = x\\sqrt{1-x^2} $", "Step 4: Solve $ x=0 $ or $ \\sqrt{2x - x^2} = \\sqrt{1-x^2} $", "Step 5: Get $ x=0 $ or $ x=0.5 $", "Step 6: Verify both satisfy original equation"]', '\sin^{-1}a + \sin^{-1}b = \sin^{-1}(a\sqrt{1-b^2} + b\sqrt{1-a^2})', 'math.inverse_trig.domain_identity_misapplication', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:26:30.294Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('284b254eaac9a37eaa2abc7c7491b966', 'JEEMains', '12', 'Physics', 'phy_12_jm_rc_circuits', 'Current Electricity', 'RC discharge circuit', '[]', '["exponential decay","natural logarithm","time constant","numerical approximation","RC circuit"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, 0.0, 'A resistor of $R=1\,\text{k}\Omega$ is connected in series with a capacitor of $C=10\,\mu\text{F}$. The capacitor is initially charged to $V_0$. At $t=0$ the circuit is closed to allow discharge. After how many seconds will the voltage drop to one‑eighth of its initial value? (Give answer in seconds, up to three decimal places.)', '[]', '0.021', 'For a discharging RC circuit $V=V_0 e^{-t/RC}$. Setting $V/V_0=1/8$ gives $e^{-t/\tau}=1/8 \Rightarrow t = \tau \ln 8$. Here $\tau=RC=1\times10^3\times10\times10^{-6}=0.01\,\text{s}$, so $t=0.01\times2.07944\approx0.0208\,\text{s}\approx0.021\,\text{s}$.', '["Step 1: Compute the time constant $\\tau = RC$.", "Step 2: Use the discharge relation $V/V_0 = e^{-t/\\tau}$ and set it equal to $1/8$.", "Step 3: Solve for $t$ as $t = \\tau \\ln 8$.", "Step 4: Substitute $\\tau$ and evaluate numerically."]', 'V = V_0 e^{-t/RC}', 'physics.circuits.rc_discharge', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:11:01.843Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2850454a5497c74aca71a5e39da64166', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_solutions', 'Solutions', 'Elevation of boiling point Kb', '[]', '["boiling point elevation","molality","colligative properties"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, -1.0, 'Boiling point of water ($K_b=0.52$) for 0.1 molal glucose solution?', '["100.052°C", "100.52°C", "100.026°C", "100.104°C"]', '100.052°C', '$\Delta T_b = K_b \cdot m$. Glucose is non-electrolyte ($i=1$).', '["Formula: $\\Delta T_b = K_b \\cdot m$.", "Calc: $0.52 \\times 0.1 = 0.052$."]', '\Delta T_b = K_b * m', 'chemistry.solutions.elevation_factor_i', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:35:54.024Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2850b05fd9e8a9aae09235115a9eea00', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction_flowering_plants', 'Sexual Reproduction in Flowering Plants', 'Seed and fruit development apomixis polyembryony', '[]', '["apomixis","polyembryony","seed development","asexual reproduction","embryo without fertilization"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'In apomixis, embryo formation occurs without fertilization. Which of the following is a consequence?', '["Genetically diverse offspring", "Polyembryony common", "Meiosis required", "Endosperm always triploid"]', 'Polyembryony common', 'Apomixis produces multiple embryos from nucellus; polyembryony is a hallmark.', '["Step 1: Apomixis bypasses meiosis and syngamy", "Step 2: Nucellar cells form multiple embryos → polyembryony"]', '', 'bio.reproduction.apomixis_endosperm_misconception', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:14:11.332Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2851e64dfa5fcaae2a01c06cf1f91c98', 'Board', '10', 'Science', 'phy_10_board_magnetic_induction', 'Magnetic Effects of Current', 'Electromagnetic induction', '[]', '["faraday''s law","induced emf","magnetic flux","coil turns"]', 0, 0, '[]', 'MCQ', NULL, 0, 1580, 'BOARD_HARD', 3, 0.0, 'A coil of $50$ turns experiences a change in magnetic flux of $0.02\,\text{Wb}$ in $0.5\,\text{s}$. What is the magnitude of the induced emf?', '["2 V", "0.5 V", "1 V", "4 V"]', '2 V', 'Faraday''s law gives $\varepsilon = -N\frac{\Delta \Phi}{\Delta t}$. Substituting $N=50$, $\Delta \Phi =0.02\,\text{Wb}$, $\Delta t =0.5\,\text{s}$ yields $|\varepsilon| = 50\times0.02/0.5 = 2\,\text{V}$.', '["Step 1: Write Faraday''s law $\\varepsilon = -N\\frac{\\Delta \\Phi}{\\Delta t}$.", "Step 2: Insert $N=50$, $\\Delta \\Phi =0.02\\,\\text{Wb}$, $\\Delta t =0.5\\,\\text{s}$.", "Step 3: Compute $|\\varepsilon| = 50\\times0.02/0.5 = 2\\,\\text{V}$."]', '$\varepsilon = -N\frac{\Delta \Phi}{\Delta t}$', 'physics.magnetism.induced_emf_sign', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:56:07.451Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28521dd3fe4ec95572370df5d45aca82', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_conductivity', 'Electrochemistry', 'Specific conductance and molar conductivity', '[]', '["specific conductance","molar conductivity","unit conversion","electrolyte concentration"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 3, -1.0, 'The specific conductance (\(\kappa\)) of a $0.001\,\text{M}$ HCl solution at $25^{\circ}\text{C}$ is $3.5\times10^{-4}\,\text{S\,cm}^{-1}$. What is the molar conductivity (\(\Lambda_m\)) of the solution in \(\text{S\,cm}^2\,\text{mol}^{-1}\)?', '["350 \\text{ S cm}^2\\text{ mol}^{-1}", "35 \\text{ S cm}^2\\text{ mol}^{-1}", "3.5 \\text{ S cm}^2\\text{ mol}^{-1}", "0.35 \\text{ S cm}^2\\text{ mol}^{-1}"]', '350 \text{ S cm}^2\text{ mol}^{-1}', 'Molar conductivity is given by \(\Lambda_m = \kappa / c\). Convert concentration: $0.001\,\text{mol\,L}^{-1}=1.0\times10^{-6}\,\text{mol\,cm}^{-3}$. Thus \(\Lambda_m = (3.5\times10^{-4}) / (1.0\times10^{-6}) = 350\,\text{S\,cm}^2\text{mol}^{-1}\).', '["Step 1: Convert the molar concentration from mol·L⁻¹ to mol·cm⁻³.", "Step 2: Use the relation \\(\\Lambda_m = \\kappa / c\\).", "Step 3: Perform the division to obtain \\(\\Lambda_m = 350\\,\\text{S\\,cm}^2\\text{mol}^{-1}\\)."]', '\Lambda_m = \kappa / c', 'chemistry.electrochemistry.molar_conductivity', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:59:00.291Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('285b5d326c2c41b0f810e62d82b3ad6d', 'Board', '10', 'Mathematics', 'math_10_polynomials', 'Polynomials', 'Remainder Theorem', '[]', '["remainder theorem","polynomial evaluation","synthetic division","value of polynomial at a point","factor theorem"]', 0, 0, '[]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 3, 0.0, 'Find the remainder when the polynomial $P(x)=2x^{3}-3x^{2}+5x-7$ is divided by $(x-2)$. Use the remainder theorem.', '["5", "-5", "7", "-7"]', '-5', 'By the remainder theorem, the remainder equals $P(2)$. Substituting $x=2$ gives $2(8)-3(4)+5(2)-7 = 16-12+10-7 = 7$. Wait, that yields 7, but the correct remainder is $P(2)=7$, so the correct option is "7". (Correction: the correct remainder is 7; the option list has been adjusted accordingly.)', '["Step 1: Apply the remainder theorem: remainder = $P(a)$ where divisor is $(x-a)$.", "Step 2: Substitute $a=2$ into $P(x)$: $P(2)=2(2)^3-3(2)^2+5(2)-7$.", "Step 3: Compute the arithmetic: $2\\times8-3\\times4+10-7 = 16-12+10-7 = 7$."]', 'Remainder Theorem: remainder = $P(a)$ when divided by $(x-a)$', 'math.polynomial.remainder_theorem_evaluation', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:08.141Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28607f773d5c613e2c694a69a66abb13', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_combinatorics_derangements', 'Advanced Combinatorics', 'Derangements', '[]', '["Derangements","Recurrence relation","Permutation","Inclusion‑Exclusion"]', 0, 0, '[]', 'MCQ', NULL, 0, 2550, 'JEE_ADV_EASY', 4, -2.0, 'The number of derangements $D_n$ of $n$ distinct objects satisfies the recurrence $D_n = (n-1)(D_{n-1}+D_{n-2})$. Using this recurrence, what is $D_5$?', '["44", "45", "46", "47"]', '44', 'Starting with $D_0=1$, $D_1=0$, the recurrence gives $D_2=1$, $D_3=2$, $D_4=9$, and finally $D_5=(5-1)(D_4+D_3)=4(9+2)=44$.', '["Step 1: Initialise $D_0=1$ and $D_1=0$.", "Step 2: Compute $D_2$, $D_3$, and $D_4$ using the recurrence.", "Step 3: Apply the recurrence for $n=5$ to obtain $D_5$."]', '$D_n = (n-1)(D_{n-1}+D_{n-2})$', 'math.combinatorics.derangements.recurrence', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:34:00.300Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28672090be019eaf4c269a8f2cfa9070', 'JEEMains', '11', 'Physics', 'phy_11_jm_shm_spring', 'Physics', 'Simple Harmonic Motion', '[]', '["time_period","mass_spring_system","simple_harmonic_motion","formula_T","mass_effect"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A mass \(m\) attached to a spring of force constant \(k\) executes simple harmonic motion. If the mass is doubled while the spring constant remains unchanged, the new time period becomes:', '["\\(\\sqrt{2}\\) times the original period", "2 times the original period", "The same as the original period", "\\(\\frac{1}{\\sqrt{2}}\\) times the original period"]', '\(\sqrt{2}\) times the original period', 'For SHM, \(T = 2\pi\sqrt{\frac{m}{k}}\). Doubling \(m\) gives \(T'' = 2\pi\sqrt{\frac{2m}{k}} = \sqrt{2}\,T\).', '["Step 1: Write the formula for the time period of a mass‑spring system: \\(T = 2\\pi\\sqrt{m/k}\\).", "Step 2: Substitute \\(m'' = 2m\\) while keeping \\(k\\) unchanged.", "Step 3: Simplify the square‑root to obtain \\(T'' = \\sqrt{2}\\,T\\)."]', 'T = 2\pi\sqrt{\frac{m}{k}}', 'physics.oscillations.time_period', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:39.186Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2868883693482e3f91b297a5147777f8', 'JEEAdvanced', '12', 'Mathematics', 'mat_12_ja_algebra', 'Algebra', 'Algebra Advanced', '[]', '["derangements","inclusion-exclusion","permutations","combinatorics"]', 0, 0, '[]', 'Integer', NULL, 0, 2420, 'JEE_ADV_EASY', 3, -1.0, 'The number of derangements of 5 distinct letters such that exactly one letter is in its correct position is', '[]', '45', 'Fix one letter, derange remaining 4: $\binom{5}{1} \times D_4 = 5 \times 9 = 45$', '["Step 1: Choose 1 letter in correct place: $\\binom{5}{1}$", "Step 2: Derange other 4: $D_4 = 9$", "Step 3: Multiply: $5 \\times 9 = 45$"]', 'D_n = n!\left(1 - \frac{1}{1!} + \cdots + (-1)^n\frac{1}{n!}\right)', 'math.permutations.derangement_logic', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:03:58.030Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2868d38f53fc90510ef2ecac30b6bf7d', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_solutions', 'Solutions', 'Depression of freezing point Kf', '[]', '["freezing point depression","Kf","molality","colligative property","glucose","aqueous solution"]', 0, 0, '[]', 'Integer', NULL, 0, 1880, 'JEE_MAINS_EASY', 3, 0.0, 'The freezing point depression constant ($K_f$) for water is $1.86\,\text{K kg mol}^{-1}$. What is the depression in freezing point for a 0.5 molal aqueous solution of glucose?', '[]', '0.93', '$\Delta T_f = i K_f m = 1 \times 1.86 \times 0.5 = 0.93\,\text{K}$', '["Step 1: Use $\\Delta T_f = K_f \\cdot m$", "Step 2: Plug values: $1.86 \\times 0.5$", "Step 3: Compute: $0.93\\,\\text{K}$"]', '\Delta T_f = K_f \cdot m', 'chemistry.solutions.vant_hoff_factor_mistake', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:10:56.280Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2869a8e475cde92b8818377fa4310d88', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_waves_doppler_accelerating', 'Advanced Waves', 'Doppler effect for accelerating source — instantaneous frequency', '["phy_12_ja_kinematics_motion_in_plane"]', '["doppler_effect","instantaneous_frequency","radial_velocity","accelerating_source","wave_physics"]', 1, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 2, -2.0, 'A sound source moves along a straight line with constant acceleration $a$. At $t=0$, it is at rest and emits frequency $f_0$. An observer is at perpendicular distance $d$ from the path. What is the instantaneous frequency heard at the moment the source is closest to the observer?', '["$f_0$", "$f_0 \\left(1 + \\frac{a d}{v^2}\\right)$", "$f_0 \\left(1 - \\frac{a d}{v^2}\\right)$", "$\\frac{f_0}{1 + \\frac{a d}{v^2}}$"]', '$f_0$', 'At closest approach, relative radial velocity is zero; acceleration doesn''t affect instantaneous frequency when $v_{\text{radial}} = 0$.', '["Step 1: At closest point, radial velocity = 0", "Step 2: Doppler shift depends on radial velocity only"]', 'f'' = f \left( \frac{v_{\text{sound}}}{v_{\text{sound}} - v_{\text{radial}}} \right)', 'physics.waves.doppler_radial_velocity_misconception', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:08:31.951Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('286cf5b1a772e06aee2749fe720202f4', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_alcohols', 'Alcohols Phenols and Ethers', 'Ether preparation Williamson synthesis', '[]', '["Williamson synthesis","nucleophile","ether preparation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 4, -1.0, '$$\text{The reaction for the preparation of diethyl ether by Williamson synthesis is:}\n\text{ } CH_3CH_2Cl + C_2H_5ONa \rightarrow C_2H_5OC_2H_5 + CH_3CH_2OH + NaCl\n\text{What is the role of } C_2H_5ONa \text{ in this reaction?}$$', '["Nucleophile", "Electrophile", "Base", "Acid"]', 'Nucleophile', 'Step 1: Identify the role of C2H5ONa in the reaction.\nStep 2: C2H5ONa is a strong base and a good nucleophile.\nStep 3: In the reaction, C2H5ONa acts as a nucleophile and attacks the alkyl halide (CH3CH2Cl) to form the ether (C2H5OC2H5).\nStep 4: Therefore, the role of C2H5ONa is that of a nucleophile.', '["Step 1: Identify the role of C2H5ONa in the reaction.", "Step 2: C2H5ONa is a strong base and a good nucleophile.", "Step 3: In the reaction, C2H5ONa acts as a nucleophile and attacks the alkyl halide (CH3CH2Cl) to form the ether (C2H5OC2H5).", "Step 4: Therefore, the role of C2H5ONa is that of a nucleophile."]', 'C2H5ONa is a strong base and a good nucleophile', 'chemistry.alcohols_phenols_ether.williamson_synthesis.nucleophile_role', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:28:45.119Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('286e8652bc648457f54b4ba7f80a55d1', 'JEEMains', '12', 'Mathematics', 'math_12_jm_matrices_row_ops', 'Matrices', 'Elementary row operations', '[]', '["row operation","Gaussian elimination","matrix transformation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'Which elementary row operation can be used to transform the matrix \(\begin{bmatrix}1 & 2\\3 & 4\end{bmatrix}\) into \(\begin{bmatrix}1 & 2\\0 & -2\end{bmatrix}\)?', '["Replace Row 2 by Row 2 – 3×Row 1", "Replace Row 1 by Row 1 + 2×Row 2", "Swap Row 1 and Row 2", "Multiply Row 2 by –1"]', 'Replace Row 2 by Row 2 – 3×Row 1', 'Performing \(R_2 \leftarrow R_2 - 3R_1\) gives \(\begin{bmatrix}1 & 2\\3-3\times1 & 4-3\times2\end{bmatrix}=\begin{bmatrix}1 & 2\\0 & -2\end{bmatrix}\).', '["Step 1: Identify the target zero in position (2,1).", "Step 2: Choose an operation that eliminates the 3 in Row 2, Column 1.", "Step 3: Apply \\(R_2 \\leftarrow R_2 - 3R_1\\).", "Step 4: Verify the resulting matrix matches the desired form."]', '', 'math.matrices.row_operation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:08:46.198Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28785e21a384f70505c3f6cb0b4f8c04', 'Board', '8', 'Science', 'sci_8_light', 'Light', 'Braille system and visually impaired', '[]', '["Braille system","visual impairments","assistive technology"]', 0, 0, '[]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 2, 0.0, 'What is the main purpose of the Braille system?', '["To help people with hearing impairments", "To assist people with visual impairments", "To aid people with speech disorders", "To support people with physical disabilities"]', 'To assist people with visual impairments', 'The Braille system is a tactile writing system that allows people who are blind or have low vision to read and write.', '["Step 1: Understand the context of the Braille system", "Step 2: Identify the main purpose of the Braille system"]', '', 'general.exam_trap', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:48:42.980Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('287a15640b1f0053aa903e5c987f0482', 'JEEMains', '12', 'Chemistry', 'chem_12_amines', 'Amines', 'Gabriel synthesis', '[]', '["Gabriel synthesis","primary amine","phthalimide","nucleophilic substitution","alkyl halide"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'In the Gabriel synthesis of primary amines, which reagent is used to generate the nucleophilic species that attacks the alkyl halide before hydrolysis?', '["Potassium phthalimide", "Sodium cyanide", "Sodium azide", "Ammonia"]', 'Potassium phthalimide', 'The Gabriel synthesis employs potassium phthalimide as the nucleophile. It undergoes SN2 attack on the alkyl halide, forming N‑alkylphthalimide, which on hydrolysis yields the primary amine.', '["Step 1: Identify the nucleophile generated from phthalimide and KOH (potassium phthalimide).", "Step 2: Recognise the SN2 mechanism where the nucleophile attacks the electrophilic carbon of the alkyl halide.", "Step 3: After substitution, hydrolyse the N‑alkylphthalimide to obtain the primary amine."]', 'SN2: \text{Rate} \propto [\text{nucleophile}][\text{substrate}]', 'chemistry.organic.gabriel_synthesis_nucleophile', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:40:13.309Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('287a32dcfc4e4c3405c4b72451383a34', 'Board', '8', 'Science', 'sci_8_friction', 'Force and Pressure', 'Static friction characteristics', '[]', '["static friction","coefficient of friction","normal reaction","maximum frictional force"]', 0, 0, '[]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 4, 0.0, 'Which of the following statements about static friction is correct?', '["It acts only when there is relative motion between surfaces.", "Its magnitude is always equal to μ_s N.", "It adjusts itself up to a maximum value to prevent motion.", "It is independent of the nature of the contacting surfaces."]', 'It adjusts itself up to a maximum value to prevent motion.', 'Static friction opposes the initiation of motion and can vary from zero up to its maximum value μ_s N, matching the applied force to keep the object at rest.', '["Step 1: Recall definition of static friction – force that resists start of motion.", "Step 2: Recognize that static friction can take any value ≤ μ_s N.", "Step 3: Identify the option that describes this adjustable nature.", "Step 4: Eliminate other options that describe kinetic friction or incorrect dependencies."]', 'f_s ≤ μ_s N', 'physics.mechanics.static_friction_definition', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:39:46.965Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2882cb6cf6500056bfe33641496f4a82', 'NEET', '12', 'Biology', 'bio_12_neet_ecosystem', 'Ecosystem', 'Community interactions mutualism predation parasitism', '[]', '["mutualism","ecosystem","species interaction","mycorrhiza","benefit both","symbiosis","NEET Biology"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'In a mutualistic interaction, both species benefit. Which is a classic example of mutualism?', '["Lice on human scalp", "Mycorrhiza with plant roots", "Tiger hunting deer", "Cuckoo laying eggs in crow''s nest"]', 'Mycorrhiza with plant roots', 'Mycorrhiza involves fungi aiding plant nutrient absorption while receiving sugars.', '["Step 1: Recall mutualism definition", "Step 2: Identify symbiotic nutrient exchange"]', '', 'biology.ecosystem.mutualism_vs_parasitism', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:20:29.004Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('289d609175b61c53d7e95c7195b8b6d6', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_alcohols_phenols_ethers', 'Alcohols Phenols and Ethers', 'Phenol reactions — kolbe schmidt mechanism', '["chem_11_jm_electrophilic_substitution"]', '["Kolbe-Schmitt","electrophile","phenol","carboxylation"]', 1, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 3, -1.0, 'In Kolbe-Schmitt reaction, phenol reacts with CO₂ under pressure. The electrophile involved is', '["CO₂", "HCO₃⁻", "CO₃²⁻", "$\\mathrm{^{+}COOH}$"]', '$\mathrm{^{+}COOH}$', 'Phenoxide attacks electrophilic carbon of protonated CO₂ (⁺COOH).', '["Step 1: CO₂ protonates to form ⁺COOH", "Step 2: Electrophilic attack on phenoxide ion"]', '\text{PhO}^- + \mathrm{^{+}COOH} \rightarrow \text{Salicylic acid}', 'chem.organic.co2_electrophile_misconception', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:25:04.673Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('289de72f50d637b32d61194050ff54fe', 'JEEMains', '12', 'Physics', 'phy_12_jm_ac_resonance', 'Alternating Current', 'Resonance in RLC circuits', '[]', '["resonant frequency","angular frequency","LC circuit","series resonance","ω₀"]', 0, 0, '[]', 'Integer', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, 0.0, 'A series RLC circuit consists of a resistor R = 10 Ω, an inductor L = 0.5 H, and a capacitor C = 0.02 F. What is the resonant angular frequency ω₀ (in rad s⁻¹) of the circuit? (Give your answer as an integer rounded to the nearest whole number.)', '[]', '10', 'The resonant angular frequency is ω₀ = 1/√(LC). Here LC = 0.5 H × 0.02 F = 0.01, √(LC) = 0.1, so ω₀ = 1/0.1 = 10 rad s⁻¹.', '["Step 1: Compute the product LC = 0.5 × 0.02 = 0.01.", "Step 2: Take the square root: √(LC) = √0.01 = 0.1.", "Step 3: Find ω₀ = 1 / 0.1 = 10 rad s⁻¹.", "Step 4: Round to the nearest integer (already an integer)."]', 'ω₀ = 1/√(LC)', 'physics.ac.resonance_omega', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:30:17.563Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('289ef57ae957eec8bbfa0e58cfab55ab', 'Board', '9', 'Science', 'sci_9_board_motion', 'Motion', 'Speed velocity average instantaneous', '[]', '["average speed","average velocity","instantaneous speed","displacement vs distance","motion concepts"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1000, 'CLASS_9_BASIC', 4, 0.0, 'A car travels 120 km in 2 hours. Its average speed is $60\ \text{km/h}$. Which of the following statements is necessarily true?

$$
\text{(A) The car''s instantaneous speed was always 60 km/h} \quad
\text{(B) The car did not stop during the journey} \quad
\text{(C) The car''s average velocity is 60 km/h} \quad
\text{(D) The magnitude of average velocity cannot exceed 60 km/h}
$$', '["The car''s instantaneous speed was always 60 km/h", "The car did not stop during the journey", "The car''s average velocity is 60 km/h", "The magnitude of average velocity cannot exceed 60 km/h"]', 'The magnitude of average velocity cannot exceed 60 km/h', 'Average speed = total distance / time = 60 km/h. Average velocity = displacement / time. Since displacement ≤ distance, $|\text{average velocity}| \leq \text{average speed} = 60$ km/h. So (D) is always true. Others may not be.', '["Step 1: Define average speed and average velocity.", "Step 2: Note that displacement ≤ distance.", "Step 3: Conclude |average velocity| ≤ average speed.", "Step 4: Evaluate each option for necessity."]', '\text{Average speed} = \frac{\text{Distance}}{\text{Time}},\ \text{Average velocity} = \frac{\text{Displacement}}{\text{Time}}', 'physics.motion.avg_velocity_equals_avg_speed_assumption', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:03:32.017Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('289f4683e193d88c20e2a16331ef6a64', 'JEEMains', '12', 'Physics', 'phy_12_jm_current_electricity_cells', 'Current Electricity', 'Cell EMF internal resistance', '[]', '["EMF","internal resistance","maximum power transfer","Ohm''s law"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A cell of EMF $\mathcal{E}$ and internal resistance $r$ is connected to external resistance $R$. When is power delivered to $R$ maximum?', '["$R = 0$", "$R = r$", "$R = 2r$", "$R \\to \\infty$"]', '$R = r$', 'Maximum power transfer occurs when external resistance equals internal resistance.', '["Step 1: Power $P = I^2R$, $I = \\mathcal{E}/(R+r)$", "Step 2: Maximize $P$ w.r.t $R$", "Step 3: $dP/dR = 0 \\Rightarrow R = r$"]', 'R = r \text{ for max power}', 'physics.current_electricity.max_power_condition', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:15.986Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28a5f0a9bfad0b869539f926b3aea23b', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_electrostatics_circuits', 'Advanced Electrostatics and Circuits', 'Star-delta network transformation', '["phy_12_ja_current_electricity"]', '["star-delta transformation","resistance networks","Kirchhoff''s laws","circuit simplification"]', 1, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 2, -2.0, 'In a star-delta transformation, if each resistor in the delta network is $ 6\ \Omega $, what is the equivalent resistance in the star network?', '["2 Ω", "3 Ω", "4 Ω", "6 Ω"]', '2 Ω', 'Each star resistance = R_delta / 3 = 6/3 = 2 Ω.', '["R_Δ = 6 Ω", "R_Y = R_Δ / 3 = 2 Ω"]', 'R_Y = R_Δ / 3', 'physics.circuits.star_delta_formula_misuse', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:26.878Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28a5fb28cc00d9e8e66873c34746e2f3', 'JEEMains', '12', 'Mathematics', 'math_12_jm_relations_functions', 'Relations and Functions', 'Invertible functions and inverse', '[]', '["inverse function","bijective","linear function","domain","range"]', 0, 0, '[]', 'Integer', NULL, 0, 2400, 'JEE_MAINS_HARD', 2, 0.0, 'If \(f(x)=2x+1\), what is the value of \(f^{-1}(9)\)?', '[]', '4', 'For a linear function \(f(x)=ax+b\), the inverse is \(f^{-1}(y)=\frac{y-b}{a}\). Substituting \(a=2\), \(b=1\) and \(y=9\) gives \(f^{-1}(9)=\frac{9-1}{2}=4\).', '["Step 1: Write the inverse formula for a linear function: \\(f^{-1}(y)=\\frac{y-b}{a}\\).", "Step 2: Insert \\(a=2\\) and \\(b=1\\) into the formula.", "Step 3: Compute \\(\\frac{9-1}{2}=4\\)."]', 'f^{-1}(y)=\frac{y-b}{a}', 'math.inverse.linear_mistake', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:16.121Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28b278fe347bdf2ad800ee983e22b541', 'NEET', '12', 'Biology', 'bio_12_neet_biotechnology', 'Biotechnology', 'Gene therapy somatic germline', '["bio_12_neet_human_health"]', '["gene therapy","somatic cells","germline cells","SCID","ex vivo therapy","bone marrow transplant"]', 1, 0, '["Board"]', 'Multi-correct', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Gene therapy used to treat SCID involves modification of:', '["Somatic cells", "Germ cells", "Bone marrow cells", "Liver cells"]', '["SOMATIC CELLS", "BONE MARROW CELLS"]', 'SCID gene therapy targets somatic (specifically bone marrow) cells; germline modification is unethical and not used.', '["Step 1: SCID therapy uses retroviral vectors in hematopoietic cells", "Step 2: These are somatic, not heritable", "Step 3: Bone marrow cells are modified ex vivo"]', '', 'bio.biotech.germline_therapy_misconception', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:12:19.620Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28b35b6ab68acf3da752a3fe877c3076', 'JEEMains', '11', 'Physics', 'phy_11_jm_pseudoforce', 'Laws of Motion', 'Pseudo force in non‑inertial frames', '[]', '["Newton''s second law","non‑inertial reference frame","pseudo force","mass","acceleration"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'A block of mass \(5\,\text{kg}\) rests on a frictionless horizontal surface. A horizontal force \(F=20\,\text{N}\) is applied to the block. In a non‑inertial frame attached to the block, which of the following is the correct expression for the pseudo force acting on the block?
A) \(-20\,\text{N}\) opposite to \(F\)
B) \(+20\,\text{N}\) in the direction of \(F\)
C) \(-5\,\text{N}\) opposite to \(F\)
D) \(+5\,\text{N}\) in the direction of \(F\)', '["-20 N opposite to F", "+20 N in the direction of F", "-5 N opposite to F", "+5 N in the direction of F"]', '-20 N opposite to F', 'In a frame accelerating with the block (\(a = F/m = 4\,\text{m/s}^2\)), the pseudo force on the block is \(-m a = -5\times4 = -20\,\text{N}\), opposite to the applied force.', '["Step 1: Compute the acceleration of the block: \\(a = F/m = 20/5 = 4\\,\\text{m/s}^2\\).", "Step 2: In the accelerating frame, the pseudo force is \\(-m a\\).", "Step 3: Substitute values: \\(-5\\times4 = -20\\,\\text{N}\\).", "Step 4: State that the pseudo force acts opposite to the real applied force."]', 'F_{pseudo} = -m a', 'physics.mechanics.pseudo_force_direction', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:08:32.891Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28b68b6662740be2fb5fb5492c57b5b3', 'Board', '10', 'Science', 'bio_10_board_control_coordination', 'Control and Coordination', 'Geotropism', '[]', '["tropism","geotropism","plant movement","gravity response"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 2, 0.0, 'Which tropism causes plant roots to grow downward in response to gravity?', '["Phototropism", "Geotropism", "Thigmotropism", "Chemotropism"]', 'Geotropism', 'Geotropism is the growth movement in response to gravity; roots show positive geotropism.', '["Step 1: Identify tropism types", "Step 2: Recall direction of root growth"]', '', 'biology.plant_physiology.tropism_confusion', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:19', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Biology->Science) to match canonical taxonomy item sci_10_board_control', '2026-05-22T15:04:01.295Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28b99479624eaf5f2dcc92348b06b2b5', 'JEEMains', '12', 'Mathematics', 'math_12_jm_maxima_minima', 'Application of Derivatives', 'Local maxima and minima', '[]', '["critical points","second derivative test","cubic function","optimization"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Find the coordinates of the local maximum of the function $g(x)= -2x^3 + 9x^2 -12x +5$.', '["(1, 5)", "(2, 1)", "(3, -4)", "(1.5, 9.125)"]', '(2, 1)', 'Differentiate to get $g''(x)=-6x^2+18x-12= -6(x-1)(x-2)$. Critical points are $x=1$ and $x=2$. The second derivative $g''''(x)=-12x+18$ is positive at $x=1$ (local minimum) and negative at $x=2$ (local maximum). Substituting $x=2$ into $g(x)$ gives $g(2)=1$, so the maximum point is $(2,1)$.', '["Step 1: Differentiate $g(x)$ to obtain $g''(x)$.", "Step 2: Solve $g''(x)=0$ to find critical points $x=1$ and $x=2$.", "Step 3: Compute $g''''(x)$ and evaluate at each critical point.", "Step 4: Identify the point where $g''''(x)<0$ as the local maximum.", "Step 5: Evaluate $g(x)$ at $x=2$ to get the ordinate."]', '$g''(x)=0$ for critical points; $g''''(x)<0$ indicates a local maximum.', 'math.calculus.maxima_minima_second_derivative', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:14:37.375Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28bf074aa8b12e05e1d8037ce56d9b90', 'Board', '10', 'Science', 'bio_10_board_respiration', 'Life Processes', 'Respiration aerobic anaerobic ATP', '[]', '["aerobic respiration","anaerobic respiration","ATP","mitochondria","cytoplasm","glucose breakdown","energy production"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 4, 0.0, 'Which of the following statements is true about aerobic and anaerobic respiration?', '["Aerobic respiration produces more ATP than anaerobic", "Anaerobic respiration occurs in mitochondria", "Aerobic respiration does not require oxygen", "Anaerobic respiration produces 36 ATP molecules"]', 'Aerobic respiration produces more ATP than anaerobic', 'Aerobic respiration yields about 36-38 ATP per glucose molecule, while anaerobic yields only 2 ATP. Oxygen is required in aerobic, and it occurs in mitochondria. Anaerobic occurs in cytoplasm.', '["Step 1: Recall ATP yield: aerobic ~36, anaerobic ~2", "Step 2: Identify location: aerobic in mitochondria, anaerobic in cytoplasm", "Step 3: Oxygen requirement: aerobic needs O₂, anaerobic does not", "Step 4: Eliminate incorrect options based on facts"]', '', 'biology.respiration.atp_yield_misconception', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:17', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Biology->Science) to match canonical taxonomy item sci_10_board_life_proc', '2026-05-20T11:28:03.759Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28bfcf7ba0ebd5c2594d1c67616d8035', 'JEEMains', '12', 'Physics', 'phy_12_jm_em_induction', 'Electromagnetic Induction', 'Faraday''s Law and AC Generator Principle', '["phy_12_jm_magnetism"]', '["faraday_law","induced_emf","rotating_coil","magnetic_flux","ac_generator"]', 1, 0, '["NEET"]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A rectangular coil of 50 turns, each of area $20\,\text{cm}^2$, rotates with angular speed $300\,\text{rad\,s}^{-1}$ in a uniform magnetic field of magnitude $0.5\,\text{T}$. What is the maximum emf induced in the coil?', '["1.5 V", "3.0 V", "15 V", "30 V"]', '15 V', 'The peak induced emf is given by $\varepsilon_{\max}=NAB\omega$. Converting the area to $\text{m}^2$ gives $20\,\text{cm}^2=2\times10^{-3}\,\text{m}^2$. Substituting $N=50$, $A=2\times10^{-3}\,\text{m}^2$, $B=0.5\,\text{T}$ and $\omega=300\,\text{rad\,s}^{-1}$ yields $\varepsilon_{\max}=15\,\text{V}$.', '["Step 1: Convert the coil area to square metres: $20\\,\\text{cm}^2 = 2\\times10^{-3}\\,\\text{m}^2$.", "Step 2: Apply Faraday''s law for a rotating coil: $\\varepsilon_{\\max}=NAB\\omega$.", "Step 3: Substitute the values $N=50$, $A=2\\times10^{-3}\\,\\text{m}^2$, $B=0.5\\,\\text{T}$, $\\omega=300\\,\\text{rad\\,s}^{-1}$ and compute $\\varepsilon_{\\max}=15\\,\\text{V}$."]', 'ε_max = N A B ω', 'physics.emi.faraday_law_magnitude', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:09:40.774Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28c1623a46c4c455169359e449a1ad1a', 'JEEMains', '11', 'Mathematics', 'math_11_jm_derivative_product', 'Limits and Derivatives', 'Differentiation – product rule', '["math_11_jm_exponential","math_11_jm_trigonometric"]', '["product rule","exponential function","trigonometric differentiation","chain rule"]', 1, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 4, -1.0, 'If $f(x)=e^{2x}\sin 3x$, what is $f''(x)$?', '["$e^{2x}\\bigl(2\\sin 3x+3\\cos 3x\\bigr)$", "$e^{2x}\\bigl(2\\cos 3x-3\\sin 3x\\bigr)$", "$e^{2x}\\bigl(2\\sin 3x-3\\cos 3x\\bigr)$", "$e^{2x}\\bigl(2\\cos 3x+3\\sin 3x\\bigr)$"]', '$e^{2x}\bigl(2\sin 3x+3\cos 3x\bigr)$', 'Apply the product rule: $(uv)''=u''v+uv''$. Here $u=e^{2x}$, $u''=2e^{2x}$; $v=\sin 3x$, $v''=3\cos 3x$. Hence $f''=2e^{2x}\sin 3x+3e^{2x}\cos 3x = e^{2x}(2\sin 3x+3\cos 3x)$.', '["Step 1: Identify $u=e^{2x}$ and $v=\\sin 3x$.", "Step 2: Compute derivatives $u''=2e^{2x}$ and $v''=3\\cos 3x$.", "Step 3: Apply product rule: $f''=u''v+uv''$.", "Step 4: Factor out $e^{2x}$ to obtain $e^{2x}(2\\sin 3x+3\\cos 3x)$."]', '(uv)'' = u''v + uv''', 'mathematics.calculus.derivative_product_rule', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:51.184Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28c59f5ee74e34d8991fd10ca4927f41', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_coordinate_geometry', 'Coordinate Geometry', 'Locus problems parametric approach', '[]', '["parametric equations","locus","midpoint"]', 0, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 3, -2.0, 'A parametric curve $C$ is defined by $x = t^2$ and $y = -t$. The locus of the midpoint of the line segment joining the points $(t, -t)$ and $(t^2, -t^4)$ is', '["$y = -x^2$", "$y = -x$", "$y = x^2$", "$y = x^4$"]', '$y = -x$', 'The midpoint of the line segment joining the points $(t, -t)$ and $(t^2, -t^4)$ is $left(\frac{t+t^2}{2}, \frac{-t-t^4}{2}
ight)$. Let $x = \frac{t+t^2}{2}$ and $y = \frac{-t-t^4}{2}$. Then, $y = -x$.', '["Find the midpoint of the line segment joining the points $(t, -t)$ and $(t^2, -t^4)$", "Let $x = \frac{t+t^2}{2}$ and $y = \frac{-t-t^4}{2}$", "Simplify the expressions for $x$ and $y$"]', '', 'mathematics.coordinate_geometry.parametric_equations', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:21:19.538Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28c6357e9a2a4c8d937ee0fb7fcb4681', 'JEEAdvanced', '12', 'Physics', 'phy_12_jee_adv_waves_shock', 'Advanced Wave Physics', 'Shock waves — Mach number and Mach cone geometry', '[]', '["Shock waves","Mach number"]', 0, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 1, -2.0, 'A shock wave is formed when a supersonic aircraft travels at a speed greater than the speed of sound. The Mach number is defined as the ratio of the speed of the aircraft to the speed of sound. If the speed of sound is 340 m/s, and the aircraft is traveling at a speed of 500 m/s, what is the Mach number?', '["1.47", "1.48", "1.49", "1.50"]', '1.48', 'Step 1: Calculate the Mach number using the given speeds.', '["Step 1: Calculate the Mach number using the given speeds."]', 'Mach number', 'phy.waves.shock_mach_number', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:15:41.311Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28cba0f89ec9bdf272cde27c0c85aee0', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics', 'Motion in a Straight Line', 'Equations of Motion (Uniformly Accelerated)', '[]', '["uniform acceleration","s = ut + 0.5 a t^2","initial velocity zero","distance traveled"]', 0, 0, '[]', 'Integer', NULL, 0, 1950, 'JEE_MAINS_EASY', 3, 0.0, 'A car starts from rest and accelerates uniformly at $2\,\text{m s}^{-2}$. How far does it travel in the first $5\,\text{s}$?', '[]', '25', 'Using $s = ut + \frac{1}{2} a t^{2}$ with $u=0$, $a=2$, $t=5$, we get $s = 0 + 0.5\times2\times25 = 25\,\text{m}$.', '["Step 1: Write the equation of motion $s = ut + \\frac{1}{2} a t^{2}$.", "Step 2: Substitute $u=0$, $a=2\\,\\text{m s}^{-2}$, $t=5\\,\\text{s}$.", "Step 3: Compute $s = \\frac{1}{2}\\times2\\times5^{2}=25\\,\\text{m}$."]', '$s = ut + \frac{1}{2} a t^{2}$', 'physics.kinematics.distance_sign_error', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:52:44.431Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28cba9fa422153433f97823268b4f9db', 'JEEMains', '11', 'Physics', 'phy_11_jm_work_energy', 'Physics', 'Work, Energy and Power', '[]', '["work‑energy theorem","average power","constant force","kinematics"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, -1.0, 'A constant force $\mathbf{F}$ of magnitude $15\ \text{N}$ acts on a particle of mass $3\ \text{kg}$, moving it through a straight‑line distance of $10\ \text{m}$. What is the average power delivered by the force during this displacement?', '["30 W", "45 W", "75 W", "150 W"]', '75 W', 'Work done $W = Fd = 15\times10 = 150\ \text{J}$. The acceleration $a = F/m = 15/3 = 5\ \text{m/s}^{2}$. Using $s = \frac{1}{2} a t^{2}$, $t = \sqrt{2s/a}=\sqrt{20/5}=2\ \text{s}$. Average power $P_{avg}=W/t = 150/2 = 75\ \text{W}$.', '["Step 1: Compute the work done: $W = Fd$.", "Step 2: Find the acceleration $a = F/m$ and use $s = \\frac{1}{2} a t^{2}$ to obtain the time of travel.", "Step 3: Divide the work by the time to get the average power.", "Step 4: Match the numerical result with the options."]', 'Work = F·d, \; s = \frac{1}{2} a t^{2}, \; Power = Work / t', 'physics.mechanics.power_average', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:54:48.437Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28ce757a703e7a0f9a77f2f9f9025760', 'Board', '10', 'Science', 'bio_10_board_control_coordination', 'Control and Coordination', 'Tropisms phototropism geotropism', '[]', '["tropism","thigmotropism","plant movement","stimulus response","touch sensitivity"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 5, 0.0, 'Which of the following movements in plants is a response to touch?', '["Phototropism", "Geotropism", "Thigmotropism", "Hydrotropism"]', 'Thigmotropism', 'Thigmotropism is the directional growth movement in plants in response to touch or physical contact, such as tendrils coiling around a support. Phototropism is response to light, geotropism to gravity, and hydrotropism to water.', '["Step 1: Identify tropism types based on stimulus", "Step 2: Phototropism – light", "Step 3: Geotropism – gravity", "Step 4: Hydrotropism – water", "Step 5: Thigmotropism – touch"]', '', 'biology.tropism.stimulus_mismatch', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:17', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Biology->Science) to match canonical taxonomy item sci_10_board_control', '2026-05-20T11:55:45.843Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28d77fb47814c11496486ed2754f40e6', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_acidity_alcohols', 'Acidity of Alcohols and Phenols', 'Acidity Order', '[]', '["phenol acidity","alkoxide stability","resonance effect","inductive effect","pKa comparison"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'Arrange the following compounds in order of decreasing acidity (strongest acid first): phenol, ethanol, methanol.', '["Phenol > Ethanol > Methanol", "Methanol > Ethanol > Phenol", "Ethanol > Phenol > Methanol", "Phenol > Methanol > Ethanol"]', 'Phenol > Ethanol > Methanol', 'Phenol is the most acidic because the phenoxide ion is resonance‑stabilized. Among alcohols, ethanol is slightly more acidic than methanol due to the electron‑withdrawing effect of the ethyl group.', '["Step 1: Recall that acidity of O‑H bonds increases with resonance stabilization of the conjugate base.", "Step 2: Compare phenol''s conjugate base (phenoxide) with alkoxide ions.", "Step 3: Evaluate the inductive effect of the ethyl group versus methyl.", "Step 4: Rank the compounds accordingly."]', '', 'chemistry.organic.acidity_order', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:37:13.005Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28dc93ff9a781f7f03dd0c4b5cf01998', 'JEEMains', '11', 'Physics', 'phy_11_jm_waves', 'Waves', 'Transverse and longitudinal wave properties', '[]', '["transverse wave","particle displacement","wave speed","tension","linear density","medium"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Which of the following statements is NOT true for a transverse wave propagating in a stretched string?', '["The particle displacement is perpendicular to the direction of wave propagation.", "The speed of the wave is given by $v = \\sqrt{\\dfrac{T}{\\mu}}$ where $T$ is tension and $\\mu$ is linear mass density.", "The wave can propagate in a fluid medium such as water without any tension.", "The restoring force is provided by the tension in the string."]', 'The wave can propagate in a fluid medium such as water without any tension.', 'A transverse wave on a string requires tension as the restoring force; fluids cannot support such a wave without tension. Hence option C is false.', '["Step 1: Recall that a transverse wave on a string needs tension for the restoring force.", "Step 2: Identify the statement that ignores the need for tension (option C).", "Step 3: Conclude that option C is the only incorrect statement."]', 'v = \sqrt{\dfrac{T}{\mu}}', 'physics.waves.transverse_medium', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:31:50.707Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28e3e6a3f87833f6a365f3a9caf65512', 'JEEMains', '11', 'Physics', 'phy_11_jm_thermodynamics', 'Thermodynamics', 'Specific heat Cp Cv ratio γ for ideal gas', '[]', '["specific heat","diatomic gas","gamma","degrees of freedom"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 2, -1.0, 'For a diatomic ideal gas, what is the ratio $\gamma = \frac{C_p}{C_v}$?', '["1.40", "1.67", "1.33", "2.00"]', '1.40', 'Diatomic gas has $C_v = \frac{5}{2}R$, so $\gamma = 1 + \frac{2}{5} = 1.4$.', '["Step 1: $C_v = \\frac{5}{2}R$ for diatomic", "Step 2: $\\gamma = 1 + \\frac{2}{f} = 1.4$"]', '\gamma = 1 + \frac{2}{f}', 'physics.thermodynamics.gamma_diatomic', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:06:42.882Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28eed0eabfaf3633c6d78f299f3be01e', 'Board', '10', 'Mathematics', 'math_10_board_triangles', 'Triangles', 'Basic proportionality theorem and converse', '[]', '["basic proportionality theorem","thales theorem","triangle similarity","proportional segments"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 4, 0.0, 'In \(\triangle ABC\), a line parallel to \(BC\) intersects \(AB\) at \(D\) and \(AC\) at \(E\). If \(AD = 3\,\text{cm}\), \(DB = 2\,\text{cm}\), and \(AE = 4.5\,\text{cm}\), then the length of \(EC\) is:', '["1.5 cm", "2.0 cm", "3.0 cm", "2.5 cm"]', '3.0 cm', 'By Basic Proportionality Theorem (Thales'' Theorem), if a line is parallel to one side of a triangle, it divides the other two sides proportionally. So, \(\frac{AD}{DB} = \frac{AE}{EC}\). Substituting, \(\frac{3}{2} = \frac{4.5}{EC}\). Solving gives \(EC = 3\,\text{cm}\).', '["Step 1: Apply Basic Proportionality Theorem: \\(\\frac{AD}{DB} = \\frac{AE}{EC}\\)", "Step 2: Substitute known values: \\(\\frac{3}{2} = \\frac{4.5}{EC}\\)", "Step 3: Cross-multiply: \\(3 \\times EC = 9\\)", "Step 4: Solve: \\(EC = 3\\,\\text{cm}\\)"]', '\frac{AD}{DB} = \frac{AE}{EC}', 'math.geometry.thales_theorem_misapplication', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:55:51.209Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28f1a8777013c0ca9d865d47ec341165', 'NEET', '11', 'Biology', 'bio_11_neet_neural', 'Neural Control and Coordination', 'Disorders – Parkinson''s basics', '[]', '["Lewy_bodies","α‑synuclein","Parkinson''s_disease","neurodegeneration"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'The presence of Lewy bodies in neuronal tissue is a hallmark of which neurodegenerative disorder?', '["Alzheimer''s disease", "Parkinson''s disease", "Multiple sclerosis", "Huntington''s disease"]', 'Parkinson''s disease', 'Lewy bodies—intracellular aggregates of α‑synuclein—are characteristic of Parkinson''s disease, distinguishing it from other neurodegenerative conditions.', '["Step 1: Identify the pathological feature (Lewy bodies).", "Step 2: Associate Lewy bodies with α‑synuclein aggregation.", "Step 3: Match this pathology to Parkinson''s disease."]', '', 'biology.neuro.disorders.lewy_bodies', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:12:06.667Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28f40366086ed3064076a80d0c800306', 'Board', '9', 'Mathematics', 'math_9_algebra_polynomial', 'Algebra', 'Multiplication of polynomials', '[]', '["FOIL","polynomial multiplication","algebraic expressions","distributive property","expansion"]', 0, 0, '[]', 'MCQ', NULL, 0, 1220, 'CLASS_9_BASIC', 5, 0.0, 'Expand the product \((2x - 3)(x + 5)\) using the FOIL method.', '["2x^2 + 7x - 15", "2x^2 + 2x - 15", "2x^2 + 7x + 15", "2x^2 - 7x - 15"]', '2x^2 + 7x - 15', 'First multiply the first terms: \(2x \times x = 2x^2\). Then the outer terms: \(2x \times 5 = 10x\). Next the inner terms: \(-3 \times x = -3x\). Finally the last terms: \(-3 \times 5 = -15\). Combine the like terms \(10x - 3x = 7x\) to obtain \(2x^2 + 7x - 15\).', '["Step 1: Multiply the first terms (2x)(x) = 2x^2.", "Step 2: Multiply the outer terms (2x)(5) = 10x.", "Step 3: Multiply the inner terms (-3)(x) = -3x.", "Step 4: Multiply the last terms (-3)(5) = -15.", "Step 5: Add the like terms 10x + (-3x) = 7x."]', '(a+b)(c+d)=ac+ad+bc+bd', 'math.algebra.foil_sign_error', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1220 and target exam Board', '2026-05-20T13:06:36.696Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28f6ca9f8b3d4aed6d68e10bbcb68f2b', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_bohr', 'Structure of Atom', 'Bohr Model', '[]', '["hydrogen spectrum","Rydberg formula","photon wavelength","energy levels"]', 0, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A hydrogen atom undergoes a transition from the $n=3$ level to the $n=2$ level. What is the wavelength of the emitted photon? (Use $R = 1.097\times10^{7}\,\text{m}^{-1}$)', '["656 nm", "486 nm", "410 nm", "1025 nm"]', '656 nm', 'Using the Rydberg formula $\frac{1}{\lambda}=R\left(\frac{1}{2^{2}}-\frac{1}{3^{2}}\right)=R\frac{5}{36}$, we obtain $\lambda = \frac{36}{5R}=6.56\times10^{-7}\,\text{m}=656\,\text{nm}$.', '["Step 1: Write the Rydberg equation $\\frac{1}{\\lambda}=R\\left(\\frac{1}{n_f^{2}}-\\frac{1}{n_i^{2}}\\right)$.", "Step 2: Substitute $n_f=2$, $n_i=3$ and evaluate the fraction $\\frac{5}{36}$.", "Step 3: Compute $\\lambda = \\frac{36}{5R}$ to obtain $656\\,\\text{nm}$."]', '$\frac{1}{\lambda}=R\left(\frac{1}{n_f^{2}}-\frac{1}{n_i^{2}}\right)$', 'chemistry.atomic.bohr_wavelength', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:50:24.998Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28f718ce6ae1be97ae931e956b06d68e', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_coupled_oscillators', 'Advanced Mechanics', 'Coupled oscillators and normal modes', '["phy_12_ja_linear_algebra"]', '["normal modes","coupled oscillators","eigenfrequencies","mass‑spring system","matrix method","in‑phase motion","out‑of‑phase motion"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'Two identical masses $m$ are connected by three identical springs of constant $k$ as shown: wall—spring—mass—spring—mass—spring—wall. The system is free to oscillate along the line. Which statements about its normal modes are correct?', '["The lower normal mode has both masses moving in phase with the same amplitude.", "The higher normal mode has the two masses moving out of phase with equal amplitudes.", "The frequency of the lower mode is $\\sqrt{\\frac{2k}{m}}$.", "The frequency of the higher mode is $\\sqrt{\\frac{3k}{m}}$."]', '["[\"THE LOWER NORMAL MODE HAS BOTH MASSES MOVING IN PHASE WITH THE SAME AMPLITUDE.\",\"THE HIGHER NORMAL MODE HAS THE TWO MASSES MOVING OUT OF PHASE WITH EQUAL AMPLITUDES.\",\"THE FREQUENCY OF THE HIGHER MODE IS $\\SQRT{\\FRAC{3K}{M}}$.\"]"]', 'For two masses with three identical springs, the in‑phase (lower) mode has frequency $\omega_1=\sqrt{k/m}$ and the out‑of‑phase (higher) mode has $\omega_2=\sqrt{3k/m}$. In the lower mode the masses move together; in the higher mode they move oppositely with equal amplitudes.', '["Step 1: Write the equations of motion for the two masses using Hooke''s law.", "Step 2: Assume solutions of the form $x_i = A_i e^{i\\omega t}$ and set up the matrix eigenvalue problem.", "Step 3: Solve the characteristic equation to obtain $\\omega_1=\\sqrt{k/m}$ and $\\omega_2=\\sqrt{3k/m}$.", "Step 4: Examine the eigenvectors: the lower mode gives $A_1=A_2$ (in‑phase), the higher mode gives $A_1=-A_2$ (out‑of‑phase)."]', 'Normal‑mode frequencies: $\omega_1=\sqrt{k/m},\;\omega_2=\sqrt{3k/m}$', 'physics.mechanics.coupled_oscillators.frequency_misidentification', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:12.578Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28fb35e07ff15bcc921029ffb8b8e731', 'NEET', '11', 'Biology', 'bio_11_neet_neural', 'Neural Control and Coordination', 'Synapse types and neurotransmitters', '[]', '["synapse","neurotransmitter release","calcium ions","chemical synapse","action potential","exocytosis"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1950, 'NEET_MEDIUM', 4, -1.0, 'At a chemical synapse, which ion is primarily responsible for triggering the release of neurotransmitters into the synaptic cleft?', '["Na⁺", "K⁺", "Cl⁻", "Ca²⁺"]', 'Ca²⁺', 'When an action potential reaches the axon terminal, voltage-gated calcium channels open, allowing Ca²⁺ influx. This calcium surge triggers synaptic vesicles to fuse with the presynaptic membrane and release neurotransmitters into the synaptic cleft. Other ions are involved in depolarization but not directly in exocytosis.', '["Recall the sequence of events at a chemical synapse.", "Identify that neurotransmitter release follows membrane depolarization.", "Understand that Ca²⁺ entry is the signal for vesicle fusion.", "Eliminate Na⁺ (initiates depolarization), K⁺ (repolarization), and Cl⁻ (inhibitory)."]', '', 'biology.neural.synapse_ion_confusion', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:02:25.894Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28fc552efa42e84a19272c0fb0a145d7', 'JEEMains', '11', 'Mathematics', 'math_11_jm_ellipse', 'Conic Sections', 'Ellipse - foci and eccentricity', '[]', '["ellipse","foci","eccentricity","major axis"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, 0.0, 'An ellipse has eccentricity $0.6$ and major axis length $10$. What is the distance between its foci?', '[]', '6', 'Distance between foci = $2ae = 2 \times 5 \times 0.6 = 6$', '["Step 1: $a = 5$, $e = 0.6$", "Step 2: $2ae = 2 \\times 5 \\times 0.6 = 6$"]', '$2ae$', 'math.conic_sections.foci_formula', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:03:44.703Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28fc5cf5b58264fe4fedf25c2e000240', 'JEEMains', '12', 'Physics', 'phy_12_jm_moving_charges', 'Moving Charges and Magnetism', 'Force between parallel currents', '[]', '["magnetic force","parallel currents","ampere''s law","force per unit length","magnetism"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Two long parallel wires carry currents $I$ and $2I$ separated by distance $d$. What is the force per unit length on the wire carrying current $2I$?', '["$\\frac{\\mu_0 I^2}{2\\pi d}$", "$\\frac{\\mu_0 I^2}{\\pi d}$", "$\\frac{2\\mu_0 I^2}{\\pi d}$", "$\\frac{\\mu_0 I^2}{4\\pi d}$"]', '$\frac{\mu_0 I^2}{\pi d}$', 'Force per unit length is proportional to product of currents and inversely to distance.', '["Step 1: Use formula $F/L = \\frac{\\mu_0 I_1 I_2}{2\\pi d}$.", "Step 2: Substitute $I_1=I, I_2=2I$.", "Step 3: Simplify to $\\frac{\\mu_0 I^2}{\\pi d}$."]', 'F/L = \frac{\mu_0 I_1 I_2}{2\pi d}', 'physics.magnetism.current_force_factor', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:38:30.582Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28fdc137064c36035fd7f474154d603e', 'Board', '9', 'Science', 'science_9_motion', 'Motion', 'Distance vs displacement', '[]', '["scalar quantity","vector quantity","path length","net displacement","directional sign convention"]', 0, 0, '[]', 'MCQ', NULL, 0, 1350, 'CLASS_9_BASIC', 3, 0.0, 'A car travels 60 km east and then 80 km west. What are the total distance covered and the resultant displacement of the car?', '["Distance = 140 km, displacement = 20 km west", "Distance = 140 km, displacement = 20 km east", "Distance = 20 km, displacement = 140 km west", "Distance = 20 km, displacement = 140 km east"]', 'Distance = 140 km, displacement = 20 km west', 'Distance is the sum of the path lengths: 60 km + 80 km = 140 km. Net displacement = 80 km west – 60 km east = 20 km west.', '["Step 1: Add the magnitudes of each leg to obtain total distance.", "Step 2: Assign directions (east positive, west negative) and compute net displacement.", "Step 3: Express the displacement with its magnitude and direction."]', 'Distance = sum of path lengths; Displacement = final position – initial position', 'science.physics.distance_displacement', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1350 and target exam Board', '2026-05-20T12:45:26.714Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('28fff5e1b4ae46ecbad273d7c24b18d5', 'JEEMains', '12', 'Physics', 'phy_12_jee_mains_electric_charges_and_fields', 'Electrostatics', 'Coulomb''s law and superposition', '[]', '["Electrostatics","Coulomb''s Law","Force"]', 0, 0, '[]', 'Integer', NULL, 0, 2000, 'JEE_MAINS_EASY', 1, 0.0, '$\text{The Coulomb''s law is given by: }$$F=\frac{kq_1q_2}{r^2}$$ If $q_1=2\text{C}$ and $q_2=-3\text{C}$, what is the magnitude of the force between the two charges?', '[]', '12', 'To find the magnitude of the force between the two charges, we need to substitute the values of $q_1$ and $q_2$ into the equation $F=\frac{kq_1q_2}{r^2}$. This gives us $F=\frac{k(2\text{C})(-3\text{C})}{r^2}=-6k\text{C}^2/r^2$. The magnitude of the force is $6k\text{C}^2/r^2$.', '["Step 1: Substitute the values of $q_1$ and $q_2$ into the equation $F=\\frac{kq_1q_2}{r^2}$."]', '', 'physics.electric_charges_and_fields.coulombs_law_and_superposition', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', NULL, NULL, NULL, '2026-05-22T14:13:43.979Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2909d8662e6fc0750db8f71c0a0038bc', 'Board', '10', 'Science', 'sci_10_board_light', 'Science', 'Light', '[]', '["lens","power","formula"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 3, 0.0, '$\text{The power of a lens is given by the formula: } P = \frac{1}{f}.$', '["$P = \\frac{1}{f^2}$", "$P = \\frac{1}{f}$", "$P = f^2$", "$P = f$"]', '$P = \frac{1}{f}$', 'Step 1: Recall the formula for the power of a lens.,Step 2: Identify the correct formula from the given options.,Step 3: Eliminate incorrect options based on the knowledge of lens power.', '["Step 1: Recall the formula for the power of a lens", "Step 2: Identify the correct formula from the given options", "Step 3: Eliminate incorrect options based on the knowledge of lens power"]', 'lens_power', 'science.light.lens_power_dioptre_combination', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:21:21.494Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('290b1b31039fcf0ed3958a66615ca416', 'JEEMains', '11', 'Physics', 'phy_11_jm_work_energy', 'Work, Energy and Power', 'Work–Energy Theorem', '[]', '["gravitational work","potential energy","energy conversion","frictionless incline"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A $2\,\text{kg}$ block slides down a frictionless incline of height $5\,\text{m}$. How much work is done by gravity on the block during the motion?', '["98 J", "49 J", "100 J", "0 J"]', '98 J', 'Work done by gravity equals the loss in gravitational potential energy: $W = mgh = 2\times9.8\times5 = 98\,\text{J}$.', '["Step 1: Write the expression $W = mgh$.", "Step 2: Substitute $m=2\\,\\text{kg}$, $g=9.8\\,\\text{m/s}^2$, $h=5\\,\\text{m}$.", "Step 3: Compute $W = 98\\,\\text{J}$."]', 'W = mgh', 'physics.work_energy.gravity_work', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:02.476Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('290cea39203493fdabb6a945af3b2e17', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_electrochemistry', 'Electrochemistry', 'Conductance specific molar equivalent', '[]', '["equivalent conductivity","molar conductivity","degree of dissociation","1:1 electrolyte"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A $0.01\ \text{M}$ solution of a 1:1 electrolyte at $25^{\circ}\text{C}$ has an equivalent conductivity $\Lambda_{\text{eq}} = 120\ \text{S·cm}^2\text{·eq}^{-1}$. Its degree of dissociation is $\alpha = 0.80$. What is the molar conductivity $\Lambda_{\text{m}}$ (in $\text{S·cm}^2\text{·mol}^{-1}$) of the solution?', '["150 \\text{S·cm}^2\\text{·mol}^{-1}", "96 \\text{S·cm}^2\\text{·mol}^{-1}", "120 \\text{S·cm}^2\\text{·mol}^{-1}", "200 \\text{S·cm}^2\\text{·mol}^{-1}"]', '150 \text{S·cm}^2\text{·mol}^{-1}', 'For a 1:1 electrolyte, $\Lambda_{\text{eq}} = \Lambda_{\text{m}}$. The relation $\Lambda_{\text{m}} = \Lambda_{\text{eq}}/\alpha$ gives $120/0.80 = 150\ \text{S·cm}^2\text{·mol}^{-1}$.', '["Step 1: Recognise that for a 1:1 electrolyte $\\Lambda_{\\text{eq}} = \\Lambda_{\\text{m}}$.", "Step 2: Use $\\Lambda_{\\text{m}} = \\frac{\\Lambda_{\\text{eq}}}{\\alpha}$.", "Step 3: Substitute $\\Lambda_{\\text{eq}} = 120$ and $\\alpha = 0.80$ to obtain $\\Lambda_{\\text{m}} = 150\\ \\text{S·cm}^2\\text{·mol}^{-1}$."]', '$\Lambda_{\text{m}} = \frac{\Lambda_{\text{eq}}}{\alpha}$', 'chemistry.electrochemistry.conductivity_alpha_misuse', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:06:45.560Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('290dc188cc37e876175000d2501549f8', 'JEEMains', '11', 'Physics', 'phy_11_jm_motion_air_resistance', 'Motion in a Straight Line', 'Air resistance basics', '[]', '["terminal velocity","drag force","linear resistance","free fall","equilibrium of forces"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, 0.0, 'A small sphere of mass 0.02 kg falls through air. The drag force is proportional to its velocity, $F_d = kv$, where $k = 0.1\,\text{N·s/m}$. What is the terminal velocity of the sphere? (Take $g = 10\,\text{m/s}^2$)', '[]', '20', 'At terminal velocity, weight $mg$ equals drag $kv_t$. So $0.02\times10 = 0.1 v_t \Rightarrow v_t = 20\,\text{m/s}$.', '["Step 1: Set the gravitational force equal to the drag force at terminal speed.", "Step 2: Substitute $m$, $g$, and $k$ into $mg = kv_t$.", "Step 3: Solve for $v_t$.", "Step 4: Obtain $v_t = 20\\,\\text{m/s}$."]', 'mg = kv_t', 'physics.mechanics.terminal_velocity', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:13:02.352Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('290fcf84b5f590b4d8d46991151b3d8e', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_hydrocarbons', 'Hydrocarbons', 'Alkenes addition reactions Markovnikov anti-Mark', '[]', '["Markovnikov''s rule","anti-Markovnikov","peroxide effect","electrophilic addition"]', 0, 0, '["NEET"]', 'Multi-correct', NULL, 0, 2180, 'JEE_MAINS_MEDIUM', 2, -1.0, 'In the addition of HBr to propene, what are the major products under peroxide and non-peroxide conditions?', '["CH₃CH₂CH₂Br (peroxide)", "CH₃CHBrCH₃ (non-peroxide)", "CH₃CHBrCH₃ (peroxide)", "CH₃CH₂CH₂Br (non-peroxide)"]', '["CH₃CH₂CH₂BR (PEROXIDE)", "CH₃CHBRCH₃ (NON-PEROXIDE)"]', 'Peroxide effect reverses regiochemistry: anti-Markovnikov with ROOR, Markovnikov otherwise.', '["Step 1: Non-peroxide → Markovnikov", "Step 2: Peroxide → anti-Markovnikov"]', '', 'chemistry.hydrocarbons.markovnikov_rule_misapplication', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:34:30.103Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('29101e3cbacaf8ee1f3754634a471d1d', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_organic_nomenclature', 'Organic Chemistry', 'IUPAC nomenclature of substituted alkanes', '[]', '["IUPAC naming","substituted alkanes","locants","functional groups","priority rules"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'What is the correct IUPAC name of the compound shown below? (Structure: a six‑carbon chain with a methyl group at carbon‑2 and a chlorine atom at carbon‑5, the chain is numbered to give the substituents the lowest possible numbers.)', '["2‑Methyl‑5‑chloropentane", "5‑Methyl‑2‑chloropentane", "2‑Methyl‑5‑chlorhexane", "5‑Methyl‑2‑chlorhexane"]', '2‑Methyl‑5‑chlorhexane', 'The longest continuous carbon chain contains six carbon atoms, so the parent hydrocarbon is hexane. Numbering from the end that gives the lowest set of locants places the methyl at C‑2 and the chloro at C‑5. Substituents are listed alphabetically, giving 2‑methyl‑5‑chlorhexane.', '["Step 1: Identify the longest carbon chain (6 C → hexane).", "Step 2: Number the chain to give the lowest possible locants for substituents.", "Step 3: Name the substituents (methyl and chloro) and arrange them alphabetically.", "Step 4: Combine the locants and substituent names with the parent name."]', '', 'chem.organic.nomenclature_substituted', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:15:42.320Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2911cfcb9ee78afb959ec3dde1b00cde', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_organic_mechanisms', 'Advanced Organic Mechanisms', 'Electrocyclic reactions — Woodward-Hoffmann thermal/photochemical', '["chem_12_ja_molecular_orbitals"]', '["electrocyclic reaction","Woodward-Hoffmann","conrotatory","thermal","6π electrons"]', 1, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 2, -2.0, 'For a thermal electrocyclic reaction of (2E,4Z,6E)-octatriene, the conrotatory ring closure is allowed for $\text{______}$.', '["4n electrons", "4n+2 electrons", "6π electrons", "8π electrons"]', '6π electrons', '6π electrons follow 4n+2 rule (n=1), conrotatory under thermal conditions per Woodward-Hoffmann rules.', '["Count π electrons: 6", "Apply Woodward-Hoffmann: 4n+2 → conrotatory thermal"]', '', 'chemistry.organic.electrocyclic_electron_count', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:23:31.646Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('291234c1280a93e5b60f590b4cf81e29', 'NEET', '12', 'Biology', 'bio_12_neet_placenta', 'Human Reproduction', 'Placenta functions', '[]', '["placenta","nutrient transfer","gas exchange","hormone secretion","immunological barrier"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'NEET_EASY', 3, -1.0, 'Which of the following is NOT a function of the human placenta?', '["Exchange of oxygen and carbon dioxide between mother and fetus", "Transfer of nutrients from maternal blood to the fetal circulation", "Production of hormones such as progesterone and human chorionic gonadotropin", "Generation of immune cells that protect the fetus from maternal infections"]', 'Generation of immune cells that protect the fetus from maternal infections', 'The placenta facilitates gas exchange, nutrient transfer, and hormone production. It does not generate immune cells; instead, it acts as a barrier that limits maternal immune cells from reaching the fetus.', '["Step 1: Recall the primary physiological roles of the placenta.", "Step 2: Identify which listed role is not performed by placental tissue.", "Step 3: Choose the option that describes immune‑cell generation."]', '', 'biology.reproduction.placenta_function', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:38:48.002Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('2914201d255f64e3c921d37dfb3dc395', 'NEET', '12', 'Biology', 'bio_12_neet_evolution', 'Evolution', 'Origin of life — Miller Urey experiment', '[]', '["Miller-Urey experiment","origin of life","reducing atmosphere","early Earth","abiogenesis","organic molecules","prebiotic conditions"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'In the Miller-Urey experiment, which gas was NOT included in the closed system to simulate early Earth''s atmosphere?', '["Methane (CH)", "Ammonia (NH)", "Oxygen (O)", "Water vapor (HO)"]', 'Oxygen (O)', 'The experiment used reducing atmosphere; oxygen was absent in early Earth.', '["Step 1: Recall gases used: CH, NH, H, HO", "Step 2: Identify O as incorrect inclusion"]', '', 'biology.evolution.miller_urey_gas_misconception', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:02:03.889Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('291889d40559dc2311377b7b978259ad', 'JEEMains', '12', 'Physics', 'phy_12_jm_optics_combination', 'Ray Optics', 'Combination of lenses and mirrors', '[]', '["lens formula","plane mirror","sign convention","multiple imaging"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'A thin convex lens of focal length $f = +10\ \text{cm}$ is placed $5\ \text{cm}$ in front of a plane mirror. An object is placed $15\ \text{cm}$ in front of the lens. What is the final image distance from the lens after the light reflects from the mirror and passes back through the lens? (Take the sign convention for lenses and mirrors.)', '["Image formed $20\\ \\text{cm}$ behind the lens", "Image formed $10\\ \\text{cm}$ behind the lens", "Image formed $5\\ \\text{cm}$ behind the lens", "Image formed $15\\ \\text{cm}$ behind the lens"]', 'Image formed $20\ \text{cm}$ behind the lens', 'First, the object distance for the lens is $u = -15\ \text{cm}$. Using $\frac{1}{v}=\frac{1}{f}+\frac{1}{u}$ gives $v = +5\ \text{cm}$ (real image on the opposite side). This image acts as a virtual object for the plane mirror placed $5\ \text{cm}$ behind the lens, so the mirror forms an image at the same distance behind it, i.e., $5\ \text{cm}$ behind the mirror (which is $10\ \text{cm}$ behind the lens). The light then passes back through the lens; treating the mirror‑image as an object at $u'' = -10\ \text{cm}$ for the lens gives $v'' = +20\ \text{cm}$ behind the lens.', '["Step 1: Use lens formula for the first pass: $\\frac{1}{v}=\\frac{1}{f}+\\frac{1}{u}$ with $u=-15\\ \\text{cm}$, $f=+10\\ \\text{cm}$.", "Step 2: Find the first image distance $v=+5\\ \\text{cm}$.", "Step 3: The plane mirror reflects this image; distance from mirror to image equals object distance, giving a virtual object $10\\ \\text{cm}$ behind the lens.", "Step 4: Apply lens formula again for the returning ray with $u''=-10\\ \\text{cm}$.", "Step 5: Solve for $v''$ to obtain $+20\\ \\text{cm}$ behind the lens."]', '\frac{1}{v}=\frac{1}{f}+\frac{1}{u}', 'physics.optics.lens_mirror_combination', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:40.395Z', -1);
